quests[13573] = { id = 13573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurions Rückkehr", description = "Wir haben erst vor kurzem die Neuigkeiten von Malfurions Erwachen gehört, nur Augenblicke, bevor der Kataklysmus über uns hereinbrach.\n\nKaum, dass er zu sich gekommen war, stieß er eine mysteriöse Warnung aus: das Land würde sich spalten, wenn nichts unternommen würde, und die Schockwellen würden über Dunkelküste zusammenlaufen.\n\nDann machte er sich - Berichten zufolge - in diese Richtung auf. Ich wurde hierher geschickt, um nach ihm zu suchen, habe aber nun alle Hände damit zu tun, den Flüchtlingen zu helfen.\n\nVielleicht könnt Ihr für uns südöstlich von hier nach ihm suchen.", sourceObjective = "Sucht nach Malfurion Sturmgrimm beim Auge des Vortex südöstlich des Flüchtlingslagers in Dunkelküste.", completion = "Es gilt, keine Zeit zu verschwenden, {class}. Es nimmt jedes bisschen meiner Energie in Anspruch, die Landmasse Dunkelküstes zusammenzuhalten und zu verhindern, dass sie einfach in den Ozean gerissen wird... Ihr müsst mir gut zuhören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13575] = { id = 13575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Land im Blut", description = "Wenn wir die Naturgewalten stabilisieren möchten, so können wir jedes bisschen Hilfe gebrauchen. Die Furbolgs des Schwarzfellstammes haben diese Gegend schon lange zu ihrer Heimat erklärt und sind mit dem Land eng verbunden.\n\nIhr Schamane und Ältester Braunpfote hat große Macht über die Elemente. Seine Hilfe wäre von unschätzbarem Wert. Versucht, ihre Unterstützung zu erhalten.", sourceObjective = "Sprecht mit dem Ältesten Braunpfote im Lager der Schwarzfelle südwestlich des Auges des Vortex.", completion = "Dem großen Malfurion Sturmgrimm zolle ich viel Respekt. Ich kann mein Volk in diesen schlimmen Zeiten jedoch nicht alleine lassen. Vielleicht gibt es eine Möglichkeit, wie wir einander helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13576] = { id = 13576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenseitige Hilfe", description = "Da viele meiner Brüder vom Wahnsinn oder von der Verderbnis eingenommen worden sind, habe ich kaum eine Wahl, als mich mit Euch zu verbünden. {race}, Ihr könnt auf unsere Hilfe zählen... sobald ich weiß, dass ich auf Eure zählen kann.\n\nWie Ihr sehen könnt, haben wir hier ein paar Probleme mit den Feuerelementaren. Helft uns, sie zu bekämpfen, und wendet dieses Totem auf ihre feurigen Überreste an.\n\nWir werden dafür sorgen, dass sie dahin zurückgehen, wo sie herkamen - ob es ihnen gefällt oder nicht.", sourceObjective = "Benutzt das besänftigende Totem, um die Überreste von 8 unbändigen Feuerelementaren zu absorbieren.", completion = "Das Element Feuer ist einzigartig in seiner Eigenschaft, sich oft weiter auszubreiten, wenn man es willkürlich angreift... und so den Flammen noch mehr Angriffslust verleiht.\n\nWir werden jedoch besonnen vorgehen, {name}. Wir werden es endgültig bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13577] = { id = 13577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Wildekin", description = "Es gab einst viele Wildekin in Dunkelküste. Sie waren so eng mit dem Land verbunden, das vom Kataklysmus zerstört wurde, dass ihre Zahlen stark zurückgingen.\n\nAroom ist der letzte Wildekin seines Stammes; er ist ein mächtiger Ältester mit einer starken Verbindung zu Elune. Seine Hilfe wird zur Heilung des Landes unumgänglich sein. Ihr könnt ihn nördlich von hier beim Mondbestrahlten Bau finden.", sourceObjective = "Sprecht mit Aroom beim Mondbestrahlten Bau nördlich vom Auge des Vortex.", completion = "Die Kreatur scheint versunken in tiefe Trauer. Ihre Augen starren durch Euch hindurch, als Ihr Euch nähert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13578] = { id = 13578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arooms Abschied", description = "<Die Kreatur ruft traurig, und wendet sich Euch zu.>\n\nAroom ist Letzter von Stamm...\n\nAndere nicht ruhen... brauchen Scheiterhaufen. Bringt Aroom Federn der anderen... sie müssen ruhen.\n\nAroom hilft Euch dann.", sourceObjective = "Erhaltet 8 Federn von getöteten Wildekin.", progress = "Ihr bringt Federn?", completion = "Ich danke Euch. {race}, bald kann mein Stamm ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13579] = { id = 13579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beschützer von Ameth'Aran", description = "Nichts heilt das Land schneller als die Stärke seiner Bewohner. Wir Nachtelfen haben das Glück, dass ein paar unserer besten Verbündeten sowohl das Land als auch dessen Bewohner zugleich sind. \n\nSelenn, ein Urtum des Krieges, wurde mit der Bewachung der Ruinen von Ameth'Aran südlich von hier beauftragt. Geht dorthin und ersucht seine Hilfe.", sourceObjective = "Sprecht mit Selenn in den Ruinen von Ameth'Aran.", completion = "Wenn der große Malfurion meine Anwesenheit verlangt, so ist es meine Pflicht, dieser Aufforderung Folge zu leisten. Es ist aber auch meine Pflicht, diese Ruinen zu beschützen.\n\nVielleicht könnt Ihr mir helfen, beiden Aufgaben nachzukommen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13580] = { id = 13580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elemente beruhigen", description = "Die Geister der Feuerelemente sind nun in dem Totem aufbewahrt. Bringt es zur Spitze des Gezackten Riffs am Lodernden Strand und platziert es dort.\n\nDie besänftigende Energie des Totems wird die Elementare langsam umspülen, bis ihre Wut abgeklungen ist.\n\nIhr müsst das Totem beschützen, denn Feuer reagiert auf das Ritual der Besänftigung alles andere als wohlgesinnt.", sourceObjective = "Platziert das aufgeladene Besänftigungstotem auf der Spitze des Gezackten Riffs am Lodernden Strand und beschützt es, bis das Ritual abgeschlossen ist.", completion = "Wir stehen in Eurer Schuld, {name}. Vielleicht können wir nun mit Malfurions Hilfe den Rest von Dunkelküste retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13581] = { id = 13581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Schwarzfelle", description = "Es wird zwar nicht unverzüglich geschehen, doch bald wird der Ärger der Elementare abklingen und mein Volk wird weiterleben.\n\nIch werde Euch und Malfurion helfen, soweit es in meiner Macht steht.", sourceObjective = "Kehrt zu Malfurion Sturmgrimm beim Auge des Vortex zurück.", completion = "Das sind gute Nachrichten, {name}. Die Furbolgs mögen auf den ersten Blick wie ein Volk der Wilden erscheinen, aber ihre Verbindungen zum Land sind uralt und ihre Schamanen sind ohnesgleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13582] = { id = 13582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer Elunes", description = "Wir brauchen für Ritual besondere Flamme - Feuer Elunes.\n\nGeist Horoo ist östlich von hier. Horoo trägt Elunes Flamme. Bringt Flamme, um Geister zu Ruhe zu bringen.\n\nIhr habt Arooms Dank.", sourceObjective = "Erhaltet Elunes Fackel von Horoo dem Flammenbewahrer.", progress = "Ihr habt Fackel?", completion = "<Aroom heult in tiefen Tönen auf.>\n\nEndlich Brüder können ruhen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13583] = { id = 13583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Wildekin", description = "Wildekin bei Elune. Aroom in Eurer Schuld.\n\nAroom hilft Euch. Kehrt zu Malfurion zurück. Aroom kommt nach.", sourceObjective = "Kehrt zu Malfurion Sturmgrimm beim Auge des Vortex zurück.", completion = "Die Wildekin waren einst die Wächter des Landes. Es ist gut zu hören, dass Aroom dies nicht vergessen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13584] = { id = 13584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erde beruhigen", description = "Ich würde meine Verantwortung vernachlässigen, wenn ich meinen Posten verließe, gerade jetzt, wo so viele Elementare in den Ruinen außer Kontrolle herumtoben.\n\nLasst uns zuerst die Elementare beseitigen, bevor wir uns überlegen, wie wir Malfurion helfen können. Was meint Ihr, <kleiner/kleine:c> {class}?", sourceObjective = "Tötet 8 wütende Erdelementare.", completion = "Es ist offensichtlich, {name}. Die Elemente werden sich nicht beruhigen, bis Malfurion das Gleichgewicht wieder ins Land gebracht hat. Wenn ich ihm helfe, so gehe ich gewissermaßen auch meiner Arbeit nach.", sourceObjectiveStatus = "unverified-source-field" }
quests[13585] = { id = 13585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eid, zu beschützen", description = "Ich bin meiner Aufgabe hier so gut wie möglich nachgegangen. Sagt Malfurion, dass ich so bald wie möglich kommen werde.\n\nIch wünsche Euch viel Glück, {name}. Ich wünsche uns allen viel Glück.", sourceObjective = "Sprecht mit Malfurion Sturmgrimm beim Auge des Vortex in Dunkelküste.", completion = "Ausgezeichnete Arbeit, {name}! Selenns Hilfe dabei, den Vortex zurückzuhalten, wird unschätzbar wertvoll sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13586] = { id = 13586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Traum", description = "Unsere Anstrengungen, die Zerstörung aufzuhalten, scheinen bisher nicht ausreichend. Ich befürchte, dass wir Hilfe jenseits dieser Welt benötigen werden.\n\nDie Schattenhammerkultisten haben in der Erdspaltergrotte östlich von hier ein Portal zum von Alpträumen geplagten Smaragdgrünen Traum erstellt. Dort halten sie einen Drachen namens Thessera gefangen.\n\nGeht durch das Alptraumportal und befreit sie. Sie wird eine mächtige Verbündete für uns sein.", sourceObjective = "Begebt Euch durch das Alptraumportal in der Erdspaltergrotte und sprecht mit Thessera.", completion = "Malfurion ruft? Ja... ich kann seine Stimme durch den Traum hindurch hören...", sourceObjectiveStatus = "unverified-source-field" }
quests[13587] = { id = 13587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erwachende Alptraum", description = "Malfurions Worte sind wahr, <kleiner/kleine:c> {class}. Der Riss droht, Dunkelküste zu spalten und unsere Welt von der Euren zu trennen.\n\nLasst mich Euch helfen, solange ich kann, bevor der Riss die Zerstörung beider Orte beschleunigt.\n\nZuerst müsst Ihr mich von meinen Fesseln befreien; erlangt die smaragdgrüne Schriftrolle von dem Wächter, der in den Hallen unter uns zu finden ist.", sourceObjective = "Erhaltet die smaragdgrüne Schriftrolle von dem Alptraumwächter in der Erdspaltergrotte.", progress = "Habt Ihr es geschafft, {name}?", completion = "Ich danke Euch, {name}. Ihr habt mir meine Freiheit geschenkt. Nun lasst uns sehen, was ich Euch und Eurer Welt Gutes tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13588] = { id = 13588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge aller Stürme", description = "Zwielichtreiter kreisen über dem Vortex. Ich fürchte, es ist ihre Magie, die die kataklysmischen Kräfte gegen unsere Anstrengungen sichert.\n\nFliegt mit Thessera los, um die Reiter und das Portal, aus dem sie kamen, zu zerstören.", sourceObjective = "Fliegt mit Thessera und zerstört 12 Zwielichtreiter und das Zwielichtportal.", completion = "Das Blatt hat sich gewendet, {name}. Wir sollten in der Lage sein, weiteren Schaden zu vermeiden.\n\nEs gibt aber immer noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13589] = { id = 13589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eindringlinge der Splitterspeere", description = "Als ob wir mit dem Land und den gegen uns gewandten Elementen nicht schon genug zu tun hätten, scheint es jetzt auch noch, als habe etwas die Trolle im Nordosten aufgewiegelt. Sie marschieren für den Kampf auf. Ich weiß nicht genau, was sie vorhaben, aber sie haben bereits ein paar unserer Späher angegriffen und belagern die Kultisten beim Turm von Althalaxx.\n\nWir haben einen Trupp unserer besten Schildwachen losgeschickt, um ihrem Angriff entgegenzutreten. Ich bin mir sicher, dass sie Hilfe gebrauchen könnten, also wäre es gut, wenn Ihr Euch zu den Ruinen nordöstlich von hier begebt und Euch ihnen anschließt.", sourceObjective = "Meldet Euch bei Leutnant Morra Sternenhauch bei den Ruinen von Mathystra.", completion = "Glynda hat Euch geschickt, um uns zu helfen, ja? Es war weise von ihr, das zu tun. Ich kann Hilfe sicherlich gebrauchen.\n\nIch arbeite gerade unseren Erstlingsplan aus, um ihre Ränge nach und nach zu dezimieren. Bitte helft in der Zwischenzeit Tysha und Balthule aus, wenn Ihr könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13590] = { id = 13590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An vorderster Front", description = "Ihre Streitmächte sind geschwächt, die Vorräte zerstört und die Befehlshaber zweiten Rangs sind tot. Es ist an der Zeit, den Kampf in ihr Territorium zu verlagern und ihren Anführer zu töten. Ich bin zugegebenermaßen immer noch nicht sicher, wo die plötzliche Aggression ihren Ursprung fand, aber vielleicht finden wir in ihrem Lager weitere Informationen.\n\nNehmt den Pfeil, den Balthule vorbereitet hat, und meldet Euch bei Sandrya Mondsturz im Splitterspeertal, um am Angriff teilzunehmen. Am besten sichert Ihr Euch einen Platz auf einem unserer Nachtsäbler - zu Fuß ist es zu gefährlich.", sourceObjective = "Meldet Euch bei Jägerin Sandrya Mondsturz im Splitterspeertal.", progress = "Seid gegrüßt, {class}. Habt Ihr den Pfeil?", completion = "Gut, Euch zu treffen. Ich habe von Euren Anstrengungen, uns zu helfen gehört, und ich muss zugeben, dass ich von Eurer Hilfe gegen die Trolle ein wenig beeindruckt bin. Wir befinden uns am Ende der Schlacht und ich hoffe, Ihr seid gut vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13591] = { id = 13591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Verbindungen", description = "Der Brief von Garrosh Höllschrei bestätigt den Verdacht, der während der Offensive im Splitterspeertal aufkam. Die Anwesenheit der Verlassenen bei den Ruinen des Turms, die Vorräte der Horde und ihre Vollstrecker im Kriegslager der Splitterspeere sind erst der Anfang. Garrosh selbst hat die Splitterspeere kontaktiert, um die Offensive in Richtung Lor'danel zu treiben, und es scheint, als habe er offensichtlich auch vor, von Süden vorzustoßen.\n\nGlynda Nal'Shea benötigt diese Informationen, um die Nachtelfen auf den Angriff vorbereiten zu können.", sourceObjective = "Bringt Höllschreis Brief zu Waldläuferin Glynda Nal'Shea in Lor'danel.", progress = "Ihr seid zurück! Ich habe gehört, die Schlacht ist gut verlaufen?", completion = "Nun, das sind in der Tat beunruhigende Neuigkeiten. Ich werde sofort Boten nach Eschental senden und versuchen, Verstärkung für sie aufzustellen.\n\nIch kann Euch für all Eure Hilfe in diesen schlimmen Zeiten nicht genug danken. Heldenhafte Taten wie die Euren verdienen eine Belohnung. Ich glaube, ich habe etwas, dass Euch gute Dienste leisten wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13592] = { id = 13592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Sir Marcus Barlow beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Selbst wenn wir für den Wettkampf trainieren, ist es gut, nicht zu vergessen, dass die Geißel noch immer da draußen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13593] = { id = 13593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Sturmwind", description = "Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation von Sturmwind beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Sturmwind ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Marschall Jacob Alerius, falls Ihr ein Recke von Sturmwind werden wollt.", completion = "Wir sind stolz, dass Ihr eingewilligt habt, mit uns zu trainieren und in unserem Namen anzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13594] = { id = 13594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst die Horde nicht", description = "Evenar und die anderen Schüler taugen vielleicht nicht viel für den Kampf, aber Ihr seht so aus, als ob Ihr Euch recht wacker schlagen würdet. Dem Abschaum der Horde am anderen Ende der Straße Richtung Osten in Bathrans Schlupfwinkel muss eine Lektion erteilt werden.\n\nIhr neuer Kriegsfürst Garrosh Höllschrei führt mit ihnen nichts Gutes im Schilde. Wollt Ihr ihnen Manieren beibringen?\n\nIch würde Euch begleiten, aber mein Befehl lautet, hier zu bleiben und Orendils Schüler zu beschützen – und genau das werde ich auch tun.", sourceObjective = "Tötet 10 beliebige Mitglieder der Horde in Bathrans Schlupfwinkel.", completion = "<Die Schildwache blickt Euch einen Augenblick anerkennend an.>\n\nIhr habt Eure Sache gut gemacht, {class}. Wenn die anderen Abenteurer, die wir noch zu Gesicht bekommen werden, Euch auch nur ein wenig ähneln, sollten wir diesen Krieg gegen die Orcs und ihre Horde schneller hinter uns gebracht haben, als erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13595] = { id = 13595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit ihren eigenen Waffen", description = "Diese Kreaturen... diese sogenannte Horde... Sie haben mich in meinen besten Jahren gefällt und sie ernten mein Haar für ihre finsteren Pläne.\n\nWerdet Ihr mir helfen, dem ein Ende zu bereiten, {race}?\n\nIch habe zufällig ein paar ihrer Kräuterkundigen von etwas sprechen hören, das sie Wildfeuer nannten, am Tisch entlang des Weges. Wenn Ihr die Flasche dieses widernatürlichen Zeugs nehmen und es auf meinen toten Körper im Nordosten werfen würdet, würde er verbrennen und mein Haar würde hier nicht mehr wachsen.\n\nIch bin schon tot und es ist ein kleiner Preis, um sie aufzuhalten.", sourceObjective = "Erbeutet eine Wildfeuerflasche und werft sie auf Bathrans Leichnam, um ihn zu verbrennen.", completion = "Ihr habt mir geholfen, zur Erde zurückzukehren, {name}.\n\nJetzt wird mein Haar nicht länger für diese Kreaturen sprießen. Besser noch: Ich werde umso baldiger wieder wachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13596] = { id = 13596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhammerpläne", description = "Wir wissen nicht genau, welche Ziele die Schattenhammerkultisten südwestlich von hier verfolgen. Wir fürchten, sie wollen Lor'danel angreifen, allerdings können ihre Motive weitaus tiefer liegen.\n\nBegebt Euch zum Lager der Schattenhammer und besorgt ihre Pläne so schnell Ihr könnt, {name}. Uns bleibt möglicherweise nicht viel Zeit.", sourceObjective = "Erhaltet 6 Schattenhammerpläne aus dem Lager der Schattenhammer.", progress = "Habt Ihr die Pläne, {name}?", completion = "Ausgezeichnete Arbeit, {name}! Gebt mir einen Moment, um mit ihren Plänen vertraut zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13597] = { id = 13597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist des Distelbären", description = "In diesen Wäldern sind drei große Geister ansässig - der des Hirsches, der des Distelbären, und der des Mondpirschers. Diese Geister sind mächtige Verbündete, allerdings könnt Ihr Euch nur einem der Geister verschreiben.Wenn Ihr Euch mit dem großen Distelbärgeist verbünden wollt, so bringt diesen Weihrauch zu der Höhle östlich des Strudels. Meditiert vor dem großen Distelbärgeist, während Ihr den Weihrauch auf dem Boden vor Euch verbrennt und stellt Euch seiner Aufgabe, um seinen Segen zu erhalten. Kehrt zu mir zurück, wenn Ihr die Aufgabe meistern konntet.", sourceObjective = "Bewahrer Karithus hat Euch angewiesen, den Segen des großen Distelbärgeists einzuholen.", completion = "Seit ewigen Zeiten durchstreife ich diese Wälder und lebe in diesen Bergen. Durch Schnee und Feuer sah ich Zivilisationen kommen und gehen, während die Natur besteht. Nun hat sich die Erde selbst gegen uns gewandt und es ist offensichtlich, dass wir kämpfen müssen, um unser Vermächtnis zu bewahren.\n\nEuer Herz ist aufrecht und ich würde Euch als meinen Champion wählen. Wenn Euch die dicke Haut und Resistenz der Distelbären am Herzen liegt, so nehmt meine Gabe an. Ihr solltet jedoch wissen, dass Ihr danach von den anderen Geistern nicht mehr akzeptiert werdet, also entscheidet Euch weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[13598] = { id = 13598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerliche Arznei", description = "Mit Hilfe meiner Heilmagie habe ich keine Zweifel, dass Grimmklaue sich wieder erholen wird. Von den Wilderern jedoch, die ihm das zugefügt haben, kann ich nicht dasselbe sagen. Um während seiner Genesung seine Schmerzen zu lindern und seine Wunden zu behandeln, wäre allerdings eine Salbe von Nutzen.\n\nÖstlich von hier befinden sich die Ruinen von Lornesta. Dort unter den Steinen wachsen verschiedene rauchende Fliegenpilze, die in der feuchten Umgebung wunderbar gedeihen. Bringt mir ein paar der Fliegenpilze, sodass ich eine Salbe für unseren Freund zubereiten kann.", sourceObjective = "Sammelt 6 rauchende Fliegenpilze.", progress = "Grimmklaue ist ein recht hartnäckiger Kämpfer. Ich habe ein wenig Mitleid mit den Wilderern, obwohl ihre Absichten abscheulich waren.", completion = "Ihr habt meinen Dank, Jüngling. Mit dieser Salbe sollte sich Grimmklaue um einiges schneller erholen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13599] = { id = 13599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmklaues Rückkehr", description = "Nun, da der Bund geschlossen ist, liegt der Segen auf Euch. Es wird Euch das Reisen in diesen Landen sehr erleichtern.\n\nGrimmklaue hat sich vollständig erholt. Er hat sich auf den Weg nach Lor'danel gemacht, bevor ich etwas sagen konnte. Das bedeutet wohl, dass auch der Zeitpunkt Eurer Abreise gekommen ist.\n\nEs hat mich sehr gefreut, Eure Bekanntschaft zu machen. Lebt wohl, und leitet meine besten Wünsche an Volcor und Grimmklaue weiter.", sourceObjective = "Kehrt zu Volcor und Grimmklaue in Lor'danel zurück.", completion = "Ihr seid zurückgekehrt! Es ist gut, Euch wiederzusehen. Ich gehe davon aus, dass wir Euch für Grimmklaues Rückkehr zu danken haben?\n\nLeider... habe ich schlechte Neuigkeiten. Ich konnte das Gift nicht neutralisieren... ihr Zustand hat sich verschlechtert. Gershalla starb kurz nach Eurer Abreise und Volcor... Volcor starb kurz vor Eurer Rückkehr.\n\nDie sichere Rückkehr Grimmklaues hat er noch erlebt und er starb mit einem Lächeln im Gesicht. Ich wünschte nur, ich hätte mehr für ihn tun können.\n\nNun muss ich all meine Kräfte darauf richten, Shaldyn zu retten, also entschuldigt mich bitte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13600] = { id = 13600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt Marschall Jacob Alerius beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "<Der Marschall nimmt die Klinge von Drak'Mar entgegen.>\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13601] = { id = 13601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Flüchtlinge", description = "Bei Elune! Anscheinend haben einige derer, die wir nach dem Angriff auf das alte Auberdine totgeglaubt hatten, ein Flüchtlingslager außerhalb der Ruinen der Stadt aufgeschlagen.\n\nDie Kultisten am Lager des Schattenhammers hatten vor, kurzen Prozess mit ihnen zu machen. Bloß gut, dass Ihr ihre Stellung so erfolgreich angreifen konntet.\n\nTrefft Priesterin Alinya im Flüchtlingslager östlich des alten Auberdine tief im Süden.", sourceObjective = "Schildwache Lendra in Lor'danel möchte, dass Ihr mit Priesterin Alinya im Flüchtlingslager sprecht.", completion = "Vielen Dank, dass Ihr uns zu Hilfe eilt. Wie Ihr sehen könnt, ist die Lage der Flüchtlinge schier aussichtslos.", sourceObjectiveStatus = "unverified-source-field" }
quests[13602] = { id = 13602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga des Strandes", description = "An der Küste im Westen lauert das Böse.\n\nDer Zoramstrand ist die Ruhestätte der verfluchten Stadt Zoram, die während der Großen Zerschlagung zerstört wurde und im Meer versank. Dort liegt sie seit langer Zeit, verloren für die Nachtelfen. Verloren und beinahe vergessen.\n\nJetzt sind die Naga zurückgekehrt und wir wissen nicht aus welchen Gründen. Aber Gründe spielen keine große Rolle. Wir müssen diese Feinde vernichten und sie zurück in ihre Tiefen zwingen.", sourceObjective = "Tötet 15 beliebige Naga der Rächerflossen am Zoramstrand.", completion = "Gut gemacht, {name}. Eure Handlungen gegen die Naga am Zoramstrand waren rühmenswert.\n\nIch weiß, dass diese Heldentat nicht leicht zu vollbringen war, denn die Stärke und Arglist der Naga sind den Nachtelfen wohl bekannt. Wir wissen das, denn sie und wir haben eine gemeinsame Vergangenheit.\n\nDie Naga sind verfluchte Hochgeborene der Nachtelfen. Vor zehntausend Jahren schloss Königin Azshara in ihrer Verzweiflung einen Pakt mit den Alten Göttern, damit die Überlebenden ihres Volkes nicht in einem nassen Grab enden.\n\nDie Naga sind das Ergebnis dieses Paktes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13603] = { id = 13603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Marschall Jacob Alerius beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13604] = { id = 13604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Datenscheibe des Archivums", description = "Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort \"ARCHIVUM\".\n\nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.", sourceObjective = "Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.", progress = "Die Konsole surrt vor Energie, als sich der runde Aufnahmebehälter öffnet.", completion = "Die Platinscheibe passt perfekt in die Konsole. Sie fängt an, sich zu drehen. Weiße Lichtstrahlen scheinen die darauf befindlichen Informationen abzutasten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13605] = { id = 13605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Flüchtling", description = "Es gab ein riesiges Erdbeben und alles wurde dunkel. Meine nächste Erinnerung ist, wie ich hier als Gefangene aufwachte. Der ganze Ort ist voll von Elementaren!\n\nIch hoffe, es geht allen gut. Dieser Schattenhammerabschaum hat besser keinem meiner Freunde Leid zugefügt!\n\nSchnell, {class}, benutzt etwas Scharfes, um das Schloss hier zu öffnen. Zusammen sollten wir es bis zum Flüchtlingslager schaffen.", sourceObjective = "Begleitet Archäologin Hollee in Sicherheit.", completion = "Ah, Ihr seid der gute Mann, der meine Hollee gerettet hat!\n\nNun, ich habe für Euch eine passende Belohnung. Wir können Euch nicht genug dafür danken, sie in Sicherheit gebracht zu haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13606] = { id = 13606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freyas Siegel", description = "Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.\n\nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.\n\nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.\n\nWas soll ich sagen, {name}, das ist eine ganz schöne Zwickmühle, in der wir da stecken.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Freyas Siegel, {name}? Habt Ihr es?", completion = "Verdammt gute Arbeit, {name}. Wir sind unserem Ziel, Azeroth zu retten, einen Schritt näher!", sourceObjectiveStatus = "unverified-source-field" }
quests[13607] = { id = 13607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Himmlische Planetarium", description = "Hört mal, <Kumpel/Mädel>! Das Schicksal von Azeroth steht hier auf dem Spiel.\n\nUnsere einzige Chance ist es, rechtzeitig das Himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.\n\nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.", progress = "Habt Ihr ihn gefunden, {name}?", completion = "Es ist verschlossen? War ja klar!\n\nDann wollen wir doch mal sehen, was für Informationen wir aus diesem Müllhaufen rausholen können...", sourceObjectiveStatus = "unverified-source-field" }
quests[13609] = { id = 13609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodirs Siegel", description = "Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!\n\nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Habt Ihr das Siegel, {name}?", completion = "Ihr habt es geschafft! Ich weiß nicht wie, aber Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[13610] = { id = 13610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorims Siegel", description = "Thorim ist nicht er selbst, {name}. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.\n\nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.\n\nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!\n\nIhr müsst ihn zur Vernunft bringen und zwar schnell.\n\nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Nun, {name}? Habt Ihr's?", completion = "Ihr werdet wohl nie aufhören, mich zu beeindrucken, {name}.\n\nIhr und ich sollten mal ein Bierchen trinken gehen, nachdem wir mit all dem hier durch sind. Mein Wort drauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[13611] = { id = 13611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimirons Siegel", description = "Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.\n\nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, um sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Konntet Ihr das Siegel an Euch bringen, {name}?", completion = "Das muss man Euch wirklich lassen, {name}. Unsere Chancen stehen vielleicht nicht zum Besten, aber wenn Ihr mit anpackt fühle ich mich gleich viel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13612] = { id = 13612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Mor’shan", description = "Lok'tar, {race}!\n\nDer Feldzug hat endlich begonnen! Bald wird sich ganz Eschental in den Händen der Horde befinden.\n\nWie wir erwartet haben, zwingt unser Angriff den Feind dazu, unsere Verteidigung an jeder erdenklichen Stelle auf die Probe zu stellen.\n\nHier in Mor’shan wurde ihre Angriffskraft geschwächt! Aber die Schlinge zieht sich immer fester zu. Sie haben keine Wahl, als uns hier weiter unter Druck zu setzen.\n\nErkundet die Umgebung, {class}. Sucht nach den Überlebenden der Nachtelfen und vernichtet sie, bevor sie sich zu einem neuen Angriff sammeln können!", sourceObjective = "Kadrak beim Schutzwall von Mor'shan will, dass Ihr 5 Scharmützler des Eschentals und 5 Bogenschützen des Eschentals tötet.", completion = "Gute Arbeit, {class}!\n\nEure Bemühungen werden uns dabei helfen, die Feinde auf Trab zu halten, während wir mit unseren Streitkräften über das Land herfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13613] = { id = 13613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Gefallenen", description = "Unsere Streitkräfte schlagen sich großartig, {class}.\n\nAber so erfreulich das auch ist, es muss sich noch um die Verwundeten gekümmert werden, von denen sich noch viele auf dem Schlachtfeld befinden.\n\nIch habe eine Salbe angerührt, die den Verwundeten genug Kraft geben sollte, um zur weiteren Behandlung zum Schutzwall zurückzukehren. Bitte verabreicht sie jedem, der sie benötigt, bevor sie für unsere Sache verloren sind.", sourceObjective = "Verwendet die heilkräftige Salbe bei 5 verletzten Verteidigern von Mor’shan.", completion = "Habt Dank, {race}. Ich werde den Dienst, den Ihr der Horde geleistet habt, in meinem Bericht erwähnen.\n\nDiese Truppen werden in kürzester Zeit wieder kampfbereit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13614] = { id = 13614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Algalon", description = "Ihr habt es wirklich geschafft, {name}. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum Himmlischen Planetarium erhaltet.\n\nIhr beeilt Euch besser, <Kumpel/Mädchen>. Die Zeit drängt.", sourceObjective = "Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.", progress = "Die gleißenden Lichter der Konsole scannen mehrmals die Glasoberfläche, gerade so, als ob eine Form von Datenübermittlung erwartet würde.", completion = "Verifizierungsprozess läuft.\n\nZugang zum himmlischen Planetarium gewährt. Bitte Schlüssel entnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13615] = { id = 13615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leere Köcher", description = "Seid gegrüßt, {class}, und willkommen am Schutzwall.\n\nEs mag hier etwas chaotisch zugehen, aber seid unbesorgt. Kadrak hat diesen Stützpunkt gut abgeschottet. Nicht ein einziger Elf konnte unsere Reihen durchbrechen!\n\nWo Ihr schon mal hier seid... Ich erwarte eine neue Versorgungslieferung aus Orgrimmar. Sie müsste jeden Tag eintreffen, aber unseren Wachmännern gehen bald die Pfeile aus.\n\nBringt mir jeden, den Ihr findet und Ihr werdet es nicht bereuen.", sourceObjective = "Truun im Schutzwall von Mor’shan verlangt von Euch, 10 brauchbare Pfeile in der Umgebung des Himmelssturzsees einzusammeln.", progress = "Habt Ihr die Pfeile, die wir brauchen, {class}?", completion = "Gute Arbeit, {class}.\n\nDamit sollten wir bis zum Eintreffen der nächsten Lieferung durchhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13616] = { id = 13616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Marschall Jacob Alerius beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", progress = "Habt Ihr die Klinge errungen, nach der ich suche?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13617] = { id = 13617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Westen zum Strand", description = "{name}, ein Freund von mir könnte Eure speziellen Fähigkeiten gut gebrauchen. Sein Name ist Talen und er ist so eine Art Archäologe. Neuerdings fasziniert ihn der Untergang der alten Stadt Zoram mit ihren Schätzen.\n\nWenn Ihr ihm zur Hand gehen wollt, findet Ihr ihn im Stützpunkt an der Grotte den Weg entlang nach Westen.", sourceObjective = "Sprecht mit Talen am Stützpunkt an der Grotte im Eschental.", completion = "Hallo, {class}.\n\nWie war das? Ihr sagt, Shyela schickt Euch?\n\n\n\nSehr gut, fangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[13618] = { id = 13618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Gorat!", description = "Gorat ist einer der fähigsten Assassinen der Horde.\n\nDie bloße Erwähnung seines Namens erfüllt die Herzen unserer Gegner von der Allianz mit Angst.\n\nEr ist zuverlässig, absolut loyal, und – bisher – pünktlich.\n\nEtwas stimmt nicht, {class}.\n\nGorats Aufgabe bestand darin, den Elf zu finden und zu töten, der für diesen Angriff auf den Schutzwall verantwortlich ist.\n\nEr sollte sich irgendwo in der Gegend um den Himmelssturzsee herum aufhalten.\n\nFindet ihn!", sourceObjective = "Kadrak am Schutzwall von Mor‘shan will, dass Ihr die Gegend um den Himmelssturzsee herum nach Gorat durchsucht.", completion = "Hört gut zu, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[13619] = { id = 13619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschlussbericht", description = "<Gorat hustet schwer, als er versucht, zu sprechen.>\n\nEs war... ein Hinterhalt...\n\nWir waren... auf dem Rückweg zum Schutzwall. Die anderen... alle sind... verloren...\n\nWir haben... ihren Anführer entdeckt... \n\n<Gorat füllt sorgfältig eine Phiole mit dem Blut, das aus einer seiner Wunden quillt.>\n\nMeine Männer... müssen gerächt werden... Bringt dies... zu Kadrak...\n\nEr wird wissen, was zu tun ist...\n\n<Gorat stirbt.>", sourceObjective = "Gorat will, dass Ihr die Phiole mit Gorats Blut zu Kadrak beim Schutzwall von Mor’shan bringt.", progress = "Habt Ihr Gorat gefunden, {class}?", completion = "<Kadrak hört aufmerksam zu, während Ihr ihm Gorats letzte Worte übermittelt.>\n\nEs ist also so, wie ich befürchtet hatte. Möge er in Frieden ruhen – aber jetzt noch nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[13620] = { id = 13620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Dinah, sofort!", description = "Vielleicht war niemand der Horde so treu ergeben wie Gorat. Bisher ist er noch bei keiner Mission gescheitert, und es scheint, als ob er es nicht zulassen wollte, dass dies seine erste wird.\n\nGorat hat Euch diese Phiole zu einem bestimmten Zweck gegeben. Dinah ist die Tochter eines ehrwürdigen Schamanen und sie ist mächtiger, als es erscheint. Bringt die Phiole zu ihr und hofft, dass wir nicht zu spät kommen.", sourceObjective = "Kadrak möchte, dass Ihr die Phiole mit Gorats Blut zu Dinah am Schutzwall von Mor'shan bringt.", progress = "Was habt Ihr da, {race}?", completion = "Sehen wir uns das mal an, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13621] = { id = 13621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorats Vergeltung", description = "Das Glück ist uns heute hold, {race}.\n\nGorats Blut war noch frisch genug, sodass ich ein besonderes Ritual durchführen konnte, das mir als Kind beigebracht wurde.\n\nVerwendet dieses angereicherte Blut auf Gorats Leichnam, um seinen dort noch immer wandelnden Geist zu beschwören.\n\nErweist ihm diesen letzten Dienst. Dann kehrt hierher zurück und berichtet Kadrak.\n\nMögen die Geister Euch schützen.", sourceObjective = "Dinah will, dass Ihr Gorats machterfülltes Blut auf Gorats Leichnam anwendet und dann Hauptmann Elendilad vernichtet.", completion = "Gut gemacht, {race}.\n\nDer Hauptmann der Elfen ist tot und die Seele eines unserer geliebten Brüder ruht nun in Frieden.\n\nIch werde die Kunde von Euren Taten an meine Vorgesetzten in Orgrimmar weiterleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13622] = { id = 13622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Geschichten", description = "Die Stücke lassen sich zu einem eleganten Hammer zusammenfügen. Seine Bauweise erweckt den Eindruck, zumindest teilweise von titanischer Natur zu sein.\n\nWomöglich könnte man über die Konsole im Archivum mehr über dieses Artefakt erfahren.", sourceObjective = "Bringt die zerschmetterten Fragmente von Val'anyr zur Archivumkonsole im Archivum in Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13623] = { id = 13623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Orendil", description = "Rasch, {name}. Ich werde das Bathranshaar in diesen Beutel füllen, aber Ihr müsst es an meinen Meister Orendil Rundblatt liefern. Ihr findet ihn in Maestras Posten, einfach Richtung Süden die Straße entlang auf der linken Seite.\n\nAber seht Euch vor, wir haben Nachricht erhalten, dass der Posten von der Horde angegriffen wird!", sourceObjective = "Bringt den Beutel voll Bathranshaar zu Orendil Rundblatt in Maestras Posten im Eschental.", progress = "Ihr seid mutig, unter diesen Umständen hierher zu kommen.\n\nWie lautet Euer Anliegen, Fremder?", completion = "Also hatte Evenar Erfolg. Um es genauer zu sagen, IHR hattet Erfolg.\n\nIch kann Euch nicht genug danken, {class}, aber diese Blätter müssen noch weiter verarbeitet werden, bevor sie als Heilmittel gegen das Unheil dienen können, welches das Kind Relara dahinsiechen lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13624] = { id = 13624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Staffel nur für Euch", description = "Ich gehe davon aus, Ihr seid hier, um zu helfen, {class}. Die Lage ist so schlimm, wie sie erscheint. Um es auf den Punkt zu bringen: Wir verlieren!\n\nMeine Mädchen und ich sind die letzte Verteidigungslinie gegen die Horde, aber wir werden hier nicht verschwinden, ohne den Kampf zu ihnen zu tragen. Bereit für eine Herausforderung?\n\nIch habe eine kleine Staffel von Schildwachen, die ich Euch unterstellen könnte. Bringt sie in ihre Nähe und ich bin mir sicher, dass ihre magischen Pfeile diese Räuber und Eindringlinge vernichten werden.\n\nSprecht mich wieder an, falls Ihr Ersatz benötigt.", sourceObjective = "Verwendet eine Staffel der Schildwachen aus Maestras Posten, um 3 Zerstörer des Eschentals und 10 Eindringlinge der Horde zu vernichten.", completion = "Einer meiner Späher in den Wäldern hat mir von Euch berichtet, aber ich hatte ja keine Ahnung, wozu Ihr wirklich in der Lage seid!\n\nHabt Dank, {name}. Durch das, was ihr erreicht habt, hat sich das Blatt gewendet. Ich habe keine Zweifel mehr, dass wir sie bis zum Tagesende besiegt haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13625] = { id = 13625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reitgrundlagen", description = "Die meisten Wettkämpfe des Turniers verlangen von den Wettstreitern, dass sie den Kampf auf einem Reittier beherrschen. Um Euch mit dem berittenen Kampf vertraut zu machen, haben wir überall im nördlichen Teil des Turnierplatzes Trainingsattrappen aufgestellt.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und steigt auf das Streitross der Quel'dorei. Macht Euch mit den verfügbaren Taktiken vertraut und besiegt anschließend die drei verschiedenen Arten von Trainingsattrappen.", sourceObjective = "Trefft ein Nahkampfziel 5 Mal mit der Fähigkeit \"Zustoßen\" und wendet die Fähigkeit \"Schildbrecher\" auf 2 ungeschützte Distanzziele sowie die Fähigkeit \"Sturmangriff\" auf 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Gut gemacht, {name}. Für diejenigen, die den Kampf zu Boden gewohnt sind, ist es oft sehr schwer, den berittenen Kampf zu erlernen. Ich habe keine Zweifel daran, dass Ihr Euch mit entsprechender Übung weiterhin verbessern werdet - was weitaus mehr ist als das, was ich von manch anderen Kriegern behaupten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13626] = { id = 13626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Gefallenen zu Ehren", description = "Es gab hier zwei Menschen: Feero Eisenhand und Delgren der Läuterer. Sie waren Mitglieder einer heiligen Organisation, die als Argentumdämmerung bekannt ist. Beide fielen bei der Verteidigung des Postens gegen den ersten Angriff der Horde.\n\nIch werde Euch meinen magischen Umhang borgen. Es ist ein Geschenk von Cenarius. Mit seiner Hilfe kann ich mich unsichtbar machen.\n\nFindet die beiden Leichname und spürt Feeros Hammer sowie Delgrens Gebetsbuch auf. Feeros Leichnam ist im Hof und Delgren liegt auf der Spitze des Turms.\n\nSeht Euch vor, denn der Hexenmeister dort oben wird Euch sehen können.", sourceObjective = "Holt Feeros heiligen Hammer und das Gebetsbuch des Läuterers zurück.", progress = "Unsere Verluste sind niederschmetternd.", completion = "Ich freue mich nicht sonderlich darauf, den Brief an die Botschaft der Argentumdämmerung in Darnassus zu schreiben. Zumindest sind wir in der Lage, die meisten ihrer Besitztümer zu den Angehörigen zurückzuschicken.\n\nIch kann Euch nicht genug für Euren Mut danken, {name}. Bitte nehmt dies im Namen des Postens entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13627] = { id = 13627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie die Axt im Walde", description = "Kommt näher. Nein, nicht zu nah. Wir wollen doch keinen Grund für unnötige Verdächtigungen geben, nicht wahr?\n\nDiese Turnierhalle benötigt mehr Holz, als wir auf Lager haben, und die Kosten für einen Ferntransport von den Grizzlyhügeln werde ich auf keinen Fall zahlen. Im Westen des Kristallsangwaldes, in der Nähe des Großen Baumes, wachsen etliche junge Kristallsangeichen. Das wäre genau das Holz, das wir zum Bauen und als Gerüstmaterial bräuchten. Nehmt dieses Beil, schlagt einige Bäume und haut daraus ein paar Hölzer. Aber lasst Euch dabei bloß nicht erwischen!", sourceObjective = "Bringt 12 grob gehauene Bauhölzer zu Stumpi Sprengbolz beim Argentumturnierplatz.", progress = "Habt Ihr die \"Waren\", von denen wir gesprochen hatten?", completion = "Das ist exzellentes Bauholz und der Preis stimmt auch! Besser noch, diese angestaubten Typen vom Argentumkreuzzug werden's nie erfahren. Sie bekommen ihre heißgeliebte Turnierhalle und ich bekomme meinen Bonus für den schnellen Bauabschluß. Wenn das mal kein Gewinn für beide Seiten ist, dann weiß ich auch nicht mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[13628] = { id = 13628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut Holz", description = "Kadrak hat gerade neue Befehle für unsere Truppen erhalten. Mir ist zu Ohren gekommen, dass wir mit dem Angriff auf Eschental beginnen!\n\nIch habe viel zu wenig Vorräte, um einen Angriff zu unterhalten, und meine Lieferung aus Orgrimmar ist noch nicht eingetroffen.\n\nIch bin gezwungen, zu improvisieren und könnte Eure Hilfe gebrauchen, {class}.\n\nSprecht mit Kadrak und fragt ihn nach den Zügeln von Brutusk. Der Kodo wird Euch zum Lager des Kriegshymnenklans tragen. Sobald Ihr dort seid, sucht nach Gorka und bittet sie, Euch mit Baumstämmen zu beladen.", sourceObjective = "Truun will, dass Ihr mit Brutusk zum Lager des Kriegshymnenklans reitet.\n\nSprecht mit Kadrak, um Kadraks Zügel zu erhalten und Brutusk reiten zu können.", completion = "Willkommen, {class}. Es ist schön, zu sehen, dass die Straße zum Schutzwall von Mor'shan frei bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13629] = { id = 13629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'anyr, Hammer der Uralten Könige", description = "Die Archivumkonsole hat eine Möglichkeit angedeutet, wie die Fragmente von Val'anyr wieder zusammengefügt werden können: Ihr müsst die Fragmente ins Innere der körperlichen Form des Wesens namens Yogg-Saron bekommen.\n\nEs mag vielleicht aussichtslos klingen, doch Ihr denkt, dass ein Artefakt von solcher Macht das Risiko wert sein könnte.", sourceObjective = "Werft die zerschmetterten Teile von Val'anyr in Yogg-Sarons Schlund, während er den Zauber 'Ohrenbetäubendes Gebrüll' wirkt, und vernichtet ihn, um den neugeschmiedeten Hammer der Uralten Könige zu erhalten.\n\nDies kann nur auf dem Schwierigkeitsgrad \"Heroisch\" beendet werden und nur dann, wenn Ihr von maximal drei Wächtern von Ulduar unterstützt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13630] = { id = 13630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus diesem Grund", description = "Die Furbolgs sind von ihren Anhöhen herabgestiegen und haben die Ruinen von Ordil'Aran im Norden überrannt. Ich vermute, dass sie das getan haben, weil sie von etwas angezogen wurden, was die toten Kultisten dort entdeckt haben: drei Mondsteine.\n\nLiladris Mondbach wird Euch raten, wie Ihr mit den Furbolgs auf eine direktere Weise fertig werdet und ich werde ihr nicht widersprechen. Aber ich würde Euch darum bitten, Euch zu den Ruinen zu begeben und die Mondsteine zu deaktivieren.", sourceObjective = "Deaktiviert den blauen, den grünen und den roten Mondstein.", completion = "Habt Dank, {name}.\n\nJetzt, wo die Mondsteine von Ordil'Aran deaktiviert sind, brauchen wir uns hier nicht um weitere Überfälle der Furbolgs zu sorgen.\n\nNichtsdestotrotz sind meine Späher mit verstörenden Neuigkeiten aus dem Dorf der Furbolgs zurückgekehrt. Dort braut sich etwas zusammen.\n\nIch frage mich, ob ich Euch darum bitten kann, für mich eine Warnung nach Astranaar zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13631] = { id = 13631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende gut, alles gut", description = "Wir sollten uns jetzt besser beeilen, {name}. Wir müssen den Antwortcode von Dalaran aus übermitteln.\n\nBringt ihn zu Rhonin. Ich treffe Euch dort.", sourceObjective = "Überbringt Rhonin in Dalaran den Antwortcode Alpha.", progress = "Seid Ihr soweit, {name}?", completion = "Ihr seid hier. Lasst uns hoffen, dass das hier klappt. Um unser aller willen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13632] = { id = 13632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Fronten", description = "Die Mondpriesterin hat einen Plan, der sicherstellen soll, dass keine weiteren Furbolgs aus dem Hochland herabsteigen. Ich mache mir mehr Sorgen um diejenigen, die bereits bei den Ruinen sind und von denen einige sich direkt vor dem Posten zusammenrotten.\n\nSo unangenehm es auch sein mag, ich muss Euch bitten, Euch nach Norden in die Ruinen von Ordil'Aran zu begeben und die Furbolgs zu vernichten. Wir können nicht an zwei Fronten gleichzeitig kämpfen!\n\nHabt Dank, {class}.", sourceObjective = "Tötet 10 beliebige Furbolgs in den Ruinen von Ordil'Aran.", completion = "Wir stehen in Eurer Schuld, {class}. Wenn ich Eines über die Furbolgs weiß, dann dies: Sie schätzen es nicht, blutige Nasen zu bekommen.\n\nEs wird nicht lange dauern, bevor sie den Schwanz einziehen und in ihr Dorf zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13633] = { id = 13633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Ritter von Westfall?", description = "Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.\n\nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.\n\nEr behauptet, der Cooperfamilie in Westfall zu entstammen. Würdet Ihr Euch aufmachen und den Wohnsitz der Familie in Mondbruch in Westfall aufsuchen? Vielleicht lässt sich dort ein Beweis für seine Geschichte finden.", sourceObjective = "Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.", progress = "Habt Ihr etwas über die Herkunft des Schwarzen Ritters herausfinden können?", completion = "Ihr meint also, an der Geschichte des Schwarzen Ritters wäre etwas faul? Sehr verdächtig. Ohne jede Ehre im besten Falle und im schlimmsten ein blutdürstiger Mörder. Trotzdem können wir ihn nicht zur Rede stellen, solange wir nicht wissen, dass er in die Morde verwickelt war.\n\nTut nichts, was seinen Verdacht erregen könnte, {name}. Diskretion wird uns von Nutzen sein, während wir unsere Nachforschungen vorantreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13634] = { id = 13634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Ritter von Silberwald?", description = "Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.\n\nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.\n\nEr behauptet, aus Valgans Feld im Silberwald zu stammen, einem kleinen Gehöft an der westlichen Küste des Lordameresees. Könntet Ihr dem Hof einen Besuch abstatten und mich wissen lassen, ob seine Geschichte der Wahrheit entspricht?", sourceObjective = "Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.", progress = "Habt Ihr etwas über die Herkunft des Schwarzen Ritters herausfinden können?", completion = "Ihr meint also, an der Geschichte des Schwarzen Ritters wäre etwas faul? Sehr verdächtig. Ohne jede Ehre im besten Falle und im schlimmsten ein blutdürstiger Mörder. Trotzdem können wir ihn nicht zur Rede stellen solange wir nicht wissen, dass er in die Morde verwickelt war.\n\nTut nichts, was seinen Verdacht erregen könnte, {name}. Diskretion wird uns von Nutzen sein, während wir unsere Nachforschungen vorantreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13635] = { id = 13635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Statusbericht des südlichen Tors", description = "Wir müssen den Gebirgsjägern im Tal der Könige einen Statusbericht zukommen lassen.\n\nIch gehe davon aus, dass Ihr sowieso in diese Richtung wolltet - könntet Ihr den Bericht für mich abliefern? Nehmt den Tunnel östlich von hier und meldet Euch beim Wachposten. Der Bericht muss direkt zu Hauptmann Rugelfuß.", sourceObjective = "Liefert den Statusbericht von Pilot Hammerfuß bei Hauptmann Rugelfuß im Tal der Könige ab.", progress = "Was führt Euch hier her?", completion = "Der Statusbericht des südlichen Tors? Ausgezeichnet. Ich warte schon seit Längerem auf Neuigkeiten von dort.\n\nEs finden sich immer mehr Troggs auf den Hügeln und ich fürchte, die Außenposten dort werden als Erstes von den Aggressionen zu spüren bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13636] = { id = 13636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle für Sturmlanze", description = "Gebirgsjäger Sturmlanze muss neue Befehle bei seinem Posten der Station Algaz erhalten. Ihr stört Euch doch nicht daran, sie ihm zu bringen? Folgt der Straße bis ihr nordöstlich von hier den Bunker seht.\n\nIhr könnt ihm auch gerne bei seinen Aufgaben helfen. Natürlich würde ich Euch dafür entsprechend belohnen.", sourceObjective = "Bringt die Befehle für Sturmlanze zu Gebirgsjäger Sturmlanze in der Station Algaz.", completion = "Befehle! Mal sehen, was es zu tun gibt... ha! Mit den Rattenmenschen soll ich mich herumschlagen. Die sind hier eh schon überall, also macht das auch keinen Unterschied mehr.\n\nWollt Ihr helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13637] = { id = 13637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widdertransport", description = "Die Gebirgsjäger im Südtoraußenposten haben eine Widderlieferung für ihre Patrouillen angefordert. Ich hätte nicht gedacht, dass wir Kräfte erübrigen können, aber dank Euch können wir ihnen wenigstens einen zukommen lassen.\n\nHättet Ihr etwas dagegen, ihn für mich bei Soldat Hammerfall abzugeben? Lasst mich wissen, wenn Ihr bereit zum Aufbruch seid." }
quests[13638] = { id = 13638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Gebirgsjäger", description = "Ihr habt Euch als mehr als fähig im Kampf erwiesen. Nun habe ich eine etwas wichtigere Angelegenheit für Euch.\n\nEiner meiner Männer, Gebirgsjäger Kieselwut, wurde von den Troggs gefangen genommen, die wir am südlichen Teil der Berge bekämpfen. Naja, er gab mehr auf, als dass er wirklich gefangen genommen wurde, aber das Resultat ist das gleiche. Er wollte wohl von innen herausfinden, wer ihr Anführer ist.\n\nIhr müsst ihn da rausholen. Sie halten ihn wahrscheinlich in der Nähe der höheren Höhlen tief im Berg.", sourceObjective = "Hauptamnn Rugelfuß in Thelsamar möchte, dass Ihr den Gebirgsjäger Kieselwut findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13639] = { id = 13639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für die Ausgrabungsstätte", description = "Eisenband hat südöstlich von hier eine Ausgrabungsstätte, für die er ordentlich Sprengstoff von der Liga geschickt bekommen hat. Huldar, Miran und Saean sind gerade mit der letzten Ladung los und können wahrscheinlich Hilfe gebrauchen.\n\nWeit sind sie sicher noch nicht gekommen, so stark wie sie sind. Mit vollen Fässern ist man nicht so schnell.\n\nSie haben den normalen Weg zur Ausgrabungsstätte eingeschlagen, durch das Südtor und am Loch vorbei. Versucht, sie einzuholen und ihnen zu helfen, ja?", sourceObjective = "Findet Huldar, Miran und Saean.", completion = "Ha, es braucht mehr als einen Hinterhalt der Dunkeleisenzwerge, um uns aufzuhalten!\n\nAber Saean... ich hätte nie gedacht, dass er ein Sympathisant ist. Wir arbeiten schon seit fast einem Jahr mit ihm zusammen... vielleicht habe ich nur nicht richtig aufgepasst.\n\nIch werde mich später darüber sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13640] = { id = 13640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Managerqualitäten", description = "Truun braucht Holz, wie? Normalerweise könnte ich ihm welches liefern, aber nicht heute.\n\nDurch die ständigen Angriffe der Elfen ist das Holzschlagen zu einem gefährlichen Unterfangen geworden. Meine Peons sträuben sich und wagen sich nicht in den Wald.\n\nIhr wollt Holz? Dann überzeugt die Peons, ihre Arbeit wieder aufzunehmen.\n\nUnd sorgt dafür, dass ihnen nichts zustößt! Ich kann es mir nicht leisten, noch weitere zu verlieren!", sourceObjective = "Überzeugt demoralisierte Peons, wieder an die Arbeit zu gehen und 5 Stück frisch gespaltenes Holz zu sammeln.", progress = "Habt Ihr das Holz bekommen, das Ihr benötigt?", completion = "Es scheint, Ihr habt das eine Problem gelöst, nur um vor einem neuen zu stehen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13641] = { id = 13641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seherkristall", description = "Jetzt, da wir wissen, dass der Schwarze Ritter nicht die Wahrheit spricht, müssen wir einen Weg finden, seine Verbindung zu den toten Rittern nachzuweisen.\n\nIch kenne einen Weg um die Wahrheit über ihren Tod aufzudecken, doch er benötigt ein seltenes Material. Wir müssen einen Seherkristall auftreiben, der nur bei den unbändigen Sehern gefunden werden kann, die sich in der Nähe der Nachtelfenruinen in den Trostlosen Wäldern im Zentrum des Kristallsangwaldes versammeln. Findet einen dieser Seher, {name}, und bringt mir die Kristalle, die er bei sich trägt.", sourceObjective = "Bringt einen Seherkristall zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Habt Ihr einen Seherkristall finden können?", completion = "Der wird vollkommen genügen. Nun bleibt nur noch, ihn mit der Macht des Lichtes zu erfüllen, sodass er die Fähigkeit erhält, die unter Lügen verborgene Wahrheit zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13642] = { id = 13642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Licht getaucht", description = "Das Gebräu ist noch nicht ganz fertig. Es muss noch in das Licht von Elune getaucht werden, bevor wir auch nur daran denken können, es dem Kind zu geben.\n\nIm Westen am Falathimsee ist uns ein Ort bekannt, wo das Mondlicht der Göttin fortwährend auf die Erde fällt - bei Tag und bei Nacht. Bitte, {name}, um Relaras Willen flehe ich Euch an: Nehmt das Gebräu und badet es in Elunes Strahlen.\n\nAber hütet Euch! Seltsame Dinge gehen im Gebiet um den See vor sich und ich befürchte, dass es nicht mehr sicher ist, dorthin zu gehen.", sourceObjective = "Stellt ein eingetauchtes Gebräu her.", progress = "Hattet Ihr Schwierigkeiten, zum Licht von Elune am Falathimsee zu gelangen?", completion = "Jetzt, da das Gebräu von Elunes Licht gesegnet wurde, kann es nach Astranaar gebracht werden.\n\nEs bleibt keine Zeit zu verlieren, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13643] = { id = 13643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichten toter Männer", description = "Die Kristalle werden die Wahrheit darüber ans Tageslicht bringen, wie drei der Turnierteilnehmer gestorben sind. Bringt ihn zum Friedhof östlich des Turnierplatzes und benutzt ihn bei den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff.\n\nWenn diese Männer wirklich ermordet worden sind, dann müssen wir einen Weg finden, eine Verbindung zum Schwarzen Ritter herzustellen, bevor er wieder zuschlägt. Beobachtet genau, was der Kristall Euch zu sagen hat, {name}, denn wir müssen sicher sein, dass diese Todesfälle keine Zufälle gewesen sind.", sourceObjective = "Benutzt den Seherkristall an den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff, um herauszufinden, wie sie gestorben sind, und kehrt anschließend zu Kreuzfahrerin Rhydalla zurück.", progress = "Habt Ihr den Gräbern der erschlagenen Kämpfer einen Besuch abgestattet?", completion = "Ihr sagt also, dass Lorien Sonnenfeuer mit Gift getötet und Sir Wendell lebendig verbrannt wurde? Beides schreckliche Arten zu sterben. Nur Conall fand seinen Tod durch kalten Stahl und anhand Eurer Beschreibung war es die Tat eines Feiglings, die ihn ins Grab brachte, nicht ehrenhafter Kampf.\n\nAlle drei trainierten mit dem Schwarzen Ritter und sollten gegen ihn kämpfen. Das kann kein Zufall sein. Wir müssen einen Weg finden zu beweisen, dass es das Werk des Schwarzen Ritters gewesen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13644] = { id = 13644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Tiefen", description = "Als ich spürte, wie sich diese... Dinger... erhoben, kam ich hierher, um sie wieder in die Tiefen zurückzuschicken. Ich fand den Leichnam Eures Freundes und schleppte ihn mit, soweit ich konnte, bevor ich mir mein Fesselgelenk brach. Das ist alles, was ich tun konnte, um diese verdorbenen Tentakel abzuwehren.\n\nEs gibt einen, der die Tentakel und die Augen lenkt. Er nennt sich Bote Aphotic – Ihr habt ihn sicher schon aus dem Süden brüllen hören.\n\nDer Bote befindet sich außerhalb der Reichweite meiner Magie, aber Ihr könntet zu ihm gelangen. Falls Ihr es wagt...", sourceObjective = "Tötet Bote Aphotic.", completion = "Jetzt, da der Bote tot ist, kann ich mit der Reinigung des Sees beginnen.\n\nIch bin Euch zu tiefstem Dank verpflichtet, {name}. Ich beklage den Tod Eures Freundes, aber ich weiß, dass seine Überreste zur Rückgewinnung des Waldstückes beitragen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13645] = { id = 13645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Raene Wolfsläufer", description = "Ich bitte Euch, diesen Edelstein Raene Wolfsläufer persönlich zu übergeben. Soweit ich weiß, hält sie sich noch immer in Astranaar im Südosten auf.\n\nZumindest ist die Straße relativ sicher. Es sollte Euch also leicht fallen, dem Verlauf bis dorthin zu folgen. Natürlich, wenn es Euch lieber ist... Ich glaube, dass Schildwache Avana bereit wäre, Euch einen ihrer Nachtsäbler zu leihen, damit Ihr schneller dorthin gelangt.\n\nWie Eure Wahl auch ausfällt, lasst es Euch wohlergehen, {name}. Mögen unsere Wege sich bald wieder kreuzen.", sourceObjective = "Überbringt den leuchtenden Edelstein an Raene Wolfsläufer in Astranaar im Eschental.", progress = "Ich bin Raene Wolfsläufer. Wer mögt Ihr wohl sein?", completion = "Teronis ist tot?\n\n<Die Lady beweint leise den Verlust ihres Freundes und beruhigt sich dann einen Augenblick später.>\n\nWir müssen das Gute daran sehen. Sein Opfer war nicht umsonst. Seid Ihr bereit, dies durchzuziehen, {class}?\n\nAlso gut, gebt mir etwas Zeit, darüber nachzudenken, wie wir fortfahren sollten. Ich werde es bald wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13646] = { id = 13646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf einen Sprung nach Astranaar", description = "Ihr wart uns eine große Hilfe, {name}. Ohne Euch wären wir bereits vernichtet worden.\n\nMit dem größten Vergnügen würde ich Euch jederzeit einen meiner Nachtsäbler anvertrauen, damit Ihr mit ihm nach Astranaar im Südosten reiten könnt. Ich bin mir sicher, dass Ihr dort wichtige Angelegenheiten zu klären habt.\n\nIch würde es Euch hoch anrechnen, wenn Ihr bei Eurem Eintreffen mit meiner Schwester Schildwache Luara sprechen könntet und Ihr mitteilt, dass ich wohlauf bin.\n\nSprecht mich einfach wieder an, wenn Ihr bereit zum Aufbruch seid. Ihr könnt Euch jederzeit ein Reittier leihen.", sourceObjective = "Sprecht mit Schildwache Luara in Astranaar im Eschental.", completion = "Avana lebt?! Ich hatte schon befürchtet, sie sei tot, als ich von dem Angriff auf Maestras Posten erfuhr!\n\nWie Ihr seht, haben wir mit der Horde ebenfalls alle Hände voll zu tun.\n\nIhr habt mir das größte Geschenk gemacht, indem Ihr mir mitgeteilt habt, dass sie wohlauf ist. Wann immer Ihr wünscht, mit einem meiner Nachtsäbler zurück zu Maestras Posten zu reiten, soll er Euch gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13647] = { id = 13647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdanschluss", description = "Ihr habt den Kampf sicherlich in Euch.\n\nWisst Ihr, östlich von hier sind bei der Jagdhütte ein paar Jäger, hoch in den Bergen, die könnten einiges mit Euch gemeinsam haben. Warum besucht Ihr sie nicht und findet heraus, ob sie interessante Arbeit für Euch haben?", sourceObjective = "Sprecht mit Marek Eisenherz bei der Jagdhütte der Weltenwanderer.", completion = "Hallo auch, Junge! Die Gebirgsjäger haben Euch geschickt, hm? Ich glaube, wir haben die Arbeit, nach der Ihr sucht. Willkommen in der Jagdhütte der Weltenwanderer!", sourceObjectiveStatus = "unverified-source-field" }
quests[13648] = { id = 13648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Der Spion der Dunkeleisenzwerge", description = "Ein Spion der Dunkeleisenzwerge hat sich in der Stadt breitgemacht und Dokumente von der Forscherliga gestohlen. Jetzt versteckt er sich hier irgendwo in der Nähe. Das letzte Mal wurde er oben auf den Hügeln südlich der Stadt gesehen.\n\nJeden, der den Spion seiner Gerechtigkeit zuführen kann, erwartet eine große Belohnung. Tot oder lebendig - tot bevorzugt!", sourceObjective = "Tötet Gorick Fassschlucker.", completion = "Ihr habt den Spion gefasst! Das geschieht ihm recht! Und gute Neuigkeiten sind es für uns. Wir können uns nun etwas beruhigter um unsere Arbeit kümmern, da wir uns um ihn wenigstens nicht mehr sorgen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13649] = { id = 13649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justins spaßiger Test", description = "He da! Ihr seht aus, als könntet Ihr gut mit Bier umgehen. Doch wie gut könnt Ihr mit Eurem Trinkkrug umgehen? \n\nDie Dunkeleisenzwerge sind zurückgekommen, um unsere Feier zu ruinieren, und das nicht zu wenig. Sie mit Krügen zu bewerfen ist die beste Möglichkeit, sie aufzuhalten. Doch erst einmal wollen wir schauen, ob Ihr einen auf die alte A.L.K. hier werfen könnt.\n\nEs ist ganz leicht, nehmt einen Freibierkrug und trinkt. Geht dabei nur sicher, dass Ihr A.L.K. anseht. Sprecht mich wieder an, wenn Ihr sie fünfmal getroffen habt.", sourceObjective = "Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Boxey Bolzdreher.", sourceObjectiveStatus = "unverified-source-field" }
quests[13650] = { id = 13650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hände weg von unseren Gütern!", description = "Wir haben in der Ausgrabungsstätte ein paar unglaubliche Artefakte gefunden. Es ist nicht leicht, zu glauben, dass sie wirklich alle authentisch sind, aber es könnte sich dabei um historisch wichtige Entdeckungen handeln.\n\nLeider haben wir durch den Überfall der Troggs Zugang zu drei der wichtigsten Funde bisher verloren. Ich fürchte, die Troggs haben sie während unserer Abwesenheit gestohlen oder zerstört.\n\nBegebt Euch zur Ausgrabungsstätte und findet den umgestürzten Riesen, die übertrieben gekleidete Frau und die zerbrochene Schrifttafel und stellt sicher, dass sie noch intakt sind.", sourceObjective = "Untersucht das Artefakt des umgestürzten Riesen, das Artefakt der übertrieben gekleideten Frau und das Artefakt der zerbrochenen Schrifttafel.", completion = "Oh, das ist gut! Ich bin erleichtert... ich war wirklich besorgt, sie wären inzwischen alle kaputt. Vielen Dank, dass Ihr nachgeschaut habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13651] = { id = 13651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braucht bisschen Öl", description = "Ihr habt Euer Holz, aber die Elfen machen es Eurem Kodo unmöglich, zum Schutzwall von Mor’shan zurückzukehren.\n\nIch habe einen Läufer zum Splitterholzposten geschickt, damit er Hilfe herbeiholt. Es sollte ihre Streitkräfte nicht allzu viel Zeit kosten, den Weg wieder frei zu machen.\n\nIn der Zwischenzeit würde ich Euch bitten, uns einen Dienst zu erweisen. Rost hat unsere Schredder unbrauchbar gemacht. Mit ein wenig Schmiermittel wären sie wieder so gut wie neu.\n\nDas Öl des faulenden Schleims in der Nähe im Norden würde sich bestens dafür eignen.", sourceObjective = "Gorka im Lager des Kriegshymnenklans möchte, dass Ihr 5 natürliche Öle von den faulenden Schleimen im Eschental sammelt.", progress = "Habt Ihr das Öl gesammelt, das wir brauchen, {class}?", completion = "Habt Dank für das Öl, {class}. Jetzt haltet Euch fest!\n\nMein Läufer ist mit niederschmetternden Neuigkeiten zurückgekehrt...\n\nDer Splitterholzposten ist umzingelt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13652] = { id = 13652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Steinwerkdamms", description = "Wir sind für Eure Hilfe sehr dankbar. Wir werden mit der Zeit immer mehr von der Ausgrabungsstätte zurückerhalten und ich bin froh, dass unsere Arbeit durch die Besatzung nicht umsonst war.\n\nWir haben Eure Zeit schon arg in Anspruch genommen. Ein Freund von mir könnte Eure Hilfe sicher gut gebrauchen, wenn Ihr bereit seid, noch mehr auszuhelfen. Geht zur anderen Seite des Loch; dort befindet sich der Steinwerkdamm. Sucht dort nach Chefingenieur Hinderweir VII.", sourceObjective = "Sucht Chefingenieur Hinderweir VII am Steinwerkdamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[13653] = { id = 13653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krise am Splitterholzposten", description = "Aus dem Splitterholzposten wird keine Hilfe kommen.\n\nDie Elfen haben einen Großangriff auf unseren dortigen Stützpunkt gestartet und sie haben den Ort umzingelt!\n\nWir müssen Kadrak informieren, koste es, was es wolle!\n\nEuer Kodo wurde mit dem Holz beladen, das Ihr gesammelt habt. Lasst mich wissen, wenn Ihr bereit seid und wir greifen die feindlichen Reihen im Sturm an.", sourceObjective = "Gorka will, dass Ihr sie zum Schutzwall von Mor’shan begleitet und Euch bei Kadrak meldet.\n\nSprecht mit Ihr, wenn Ihr bereit zur Abreise seid.", completion = "Gorka...\n\nWir müssen immer auf Verluste vorbereitet sein. Ihre ehrenvollen Verdienste für die Horde werden niemals vergessen werden.\n\nAll ihre Opfer werden nicht vergeblich gewesen sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13654] = { id = 13654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas ist mit dem Knappen", description = "Jeden Tag macht der Knappe des Schwarzen Ritters Maloric eine große Sache daraus, wie er mit der Axt auf seiner Schulter in Richtung Kristallsangwald aufbricht. Er will uns weismachen, er hacke Holz, nur kehrt er niemals mit mehr als nur ein paar Zweigen zurück.\n\nNormalerweise geht er in Richtung Ruinen südwestlich des Zwielichtspiegels. Er verbringt viel Zeit dort draußen, selbst für einen Knappen, der seinem Ritter gegenüber Pflichten hat.\n\nFindet einen Weg, ihn entweder abzulenken oder außer Gefecht zu setzen, und durchsucht ihn. Sollte er etwas im Schilde führen, dann werden wir es wissen.", sourceObjective = "Beschafft einen großen Oberschenkelknochen eines skelettierten Holzfällers und setzt damit Maloric außer Gefecht. Durchsucht ihn nach Beweisen und meldet Euch anschließend bei Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Habt Ihr den Knappen durchsucht und irgendwelche Anhaltspunkte gefunden?", completion = "<Kreuzfahrerin Rhydalla untersucht den Inhalt des Beutels mit angewidertem Gesicht.>\n\nEs ist alles da, {name}: das Gift, das Lorien tötete, eine Sammlung Messer, Fackeln und Öl. Niemand hier hat Grund dazu, diese Dinge zu besitzen, und kein Knappe würde dies ohne den Befehl seines ritterlichen Meisters tun. Wir haben unseren Mörder gefunden, {name}, doch für wen arbeitet er?", sourceObjectiveStatus = "unverified-source-field" }
quests[13655] = { id = 13655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (2 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es scheint potentielle Ausgrabungsstätten in ganz Loch Modan aufzuführen. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Seht Euch das an. Ihr habt eines der gestohlenen Dokumente gefunden!\n\nWir sind sehr dankbar, dass Ihr es zurückgebracht habt. Hoffentlich ist Euch ein bisschen Gold als Finderlohn genug?", sourceObjectiveStatus = "unverified-source-field" }
quests[13656] = { id = 13656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (1 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und ausführliche Informationen über in Loch Modan einheimische Kreaturen sind darauf aufgeführt. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Hallo, Kleiner! Ihr scheint eines der gestohlenen Dokumente gefunden zu haben, hm?\n\nVielen Dank, dass Ihr es zurückgebracht habt. Wir geben Euch gerne eine kleine Belohnung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[13657] = { id = 13657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (3 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es ist mit historischen Informationen zu den wichtigen Orten in Loch Modan beschriftet. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Unsere historischen Aufzeichnungen! Beim Gedanken daran, dass das Gesindel der Dunkeleisenzwerge Informationen über unsere Vergangenheit hat, hat sich mir der Magen umgedreht.\n\nWir sind sehr dankbar, dass Ihr uns die historischen Aufzeichnungen zurückgebracht habt. Wir möchten Euch ein paar Münzen als Belohnung anbieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13658] = { id = 13658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (4 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es scheinen Informationen zu allen Transportwegen in und nach Loch Modan darauf aufgeführt zu sein. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Oha, Informationen über unsere Transportwege in ihren Händen schreien förmlich nach Ärger!!\n\nVielen Dank, dass Ihr uns das Dokument gebracht habt, bevor sie viel damit anfangen konnten! Ihr habt uns sicherlich viel Ärger erspart. Hier, nehmt ein paar Münzen als Lohn für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13659] = { id = 13659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (6 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es sind Einschätzungen zu den unterschiedlichen Bedrohungen in Loch Modan darauf aufgeführt. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Ha! Sie haben sich sicherlich darüber geärgert, wie weit unten sie auf unserer Liste mit Bedrohungen stehen! Dieses Dokument war zugegebenermaßen nicht mehr aktuell, aber immer noch einen Lacher wert.\n\nNatürlich werden wir Euch trotzdem einen Finderlohn geben, weil Ihr das Dokument zurückgebracht habt - wir sind für Eure Bemühungen sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13660] = { id = 13660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (5 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga; es ist eine detaillierte Liste aller bei den Ausgrabungen von Eisenbands Arbeitern im südöstlichen Loch Modan gefundenen Artefakte. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Unsere Artefakteliste! Ich war wirklich besorgt, dass diese Liste den Dunkeleisenzwergen dabei helfen würde, mit den Informationen die Artefakte zu stehlen.\n\nVielen Dank, dass Ihr die Liste zurückgebracht habt. Natürlich entlohnen wir Eure Mühen mit ein paar Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13661] = { id = 13661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertschätzung aus tiefstem Herzen", description = "Ihr habt alle unsere Dokumente gefunden! Wir können Euch wirklich nicht genug für Eure Mühen danken... wir hatten die Hoffnung aufgegeben. Wir waren uns ganz sicher, dass die Dunkeleisenzwerge mit diesen Informationen sehr viel Unheil anstellen könnten. Es ist gut zu wissen, dass sie mit ihren Angriffen weiterhin im Dunklen tappen werden.\n\nIch möchte Euch für alle Eure Mühen im Namen der Liga danken und Euch ein Geschenk machen. Ein Artefakt, um genau zu sein... etwas, das wir bei unseren Ausgrabungen gefunden haben. Ihr habt den Dank der gesamten Forscherliga." }
quests[13662] = { id = 13662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anerkennung erlangen", progress = "Ihr habt Euch in der Hierarchie der Bruderschaft hochgearbeitet, {race}. Wir betrachten Euch nun mit Wohlwollen. Eine ziemliche Leistung!\n\nFalls Ihr an mehr Arbeit interessiert sein solltet und damit mehr Respekt bei uns verdienen wollt, dann hört zu.\n\nWir können das feurige Fluxus veredeln, indem wir der Mischung einfache Dunkeleisenrückstände hinzufügen. Die genannten Rückstände können in den Schwarzfelstiefen gefunden werden.\n\nBringt mir so viel von den Dunkeleisenrückständen, wir Ihr nur finden könnt!", completion = "Immer her mit den Dunkeleisenrückständen!" }
quests[13663] = { id = 13663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befehle des Schwarzen Ritters", description = "Wir müssen herausfinden, wer den Schwarzen Ritter zum Turnier geschickt hat und was sich sein Meister daraus erhofft, die Konkurrenz zu töten.\n\nDie Kirin Tor haben in dieser Angelegenheit ihre Unterstützung angeboten und uns ein Werkzeug zur Verfügung gestellt, dass uns in unserer Suche helfen wird.\n\nBringt dieses verzauberte Zaumzeug zum Lager des Schwarzen Ritters am östlichen Rand des Turniergeländes und benutzt es, um Kontrolle über den Greifen des Schwarzen Ritters zu erhalten. Die Verzauberung des Zaumzeugs wird das Tier zwingen, Euch zum Wohnort seines Meisters zu bringen. Durchsucht ihn und bringt alles zurück, was Ihr finden könnt.", sourceObjective = "Erhaltet mithilfe des verzauberten Zaumzeugs Kontrolle über den Greifen des Schwarzen Ritters und reitet auf seinem Rücken zum Zielort. Beschafft Euch die gestohlene Einladung zum Turnier und die Befehle des Schwarzen Ritters, sobald Ihr dort angekommen seid, und bringt sie zurück zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Was habt Ihr herausgefunden?", completion = "<Kreuzfahrerin Rhydalla wird blass, als sie die Befehle liest.>\n\nDas kann nur eins bedeuten, {name}. Der Schwarze Ritter ist ein Anhänger des Kults der Verdammten und wurde von Arthas ausgesandt, um das Turnier zu stören!\n\nDer Schwarze Ritter hat sich als Furcht erregender Kämpfer entpuppt und Ihr werdet mindestens genauso gut sein müssen, um Ihm entgegenzutreten. Kehrt zu mir zurück, wenn Ihr Champion geworden seid, und wir werden einen Weg finden, für seine Niederlage zu sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13664] = { id = 13664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz des Schwarzen Ritters", description = "Wir müssen den finsteren Plänen des Schwarzen Ritters ein Ende setzen und unseren Widersachern zeigen, dass wir nicht untätig daneben stehen und zusehen, wie unsere Champions ermordet werden.\n\nEr wird mittlerweile annehmen, dass ihm jemand auf den Fersen ist. Fordert ihn am helllichten Tage zum Kampf heraus, {name} - wenn er nicht ablehnen oder jemanden im Dunklen ermorden kann.\n\nNehmt mein Argentumstreitross für den Kampf. Es steht in den Stallungen, in der Nähe des Argentumpavillons.\n\nSprecht dann mit Knappe Cavin im Ring der Champions. Der Knappe wird den Schwarzen Ritter zum Kampf rufen und Ihr werdet ihn für seine Taten büßen lassen.", sourceObjective = "Besiegt den Schwarzen Ritter und sprecht anschließend mit Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Ist es vollbracht?", completion = "Mit dem Tod des Schwarzen Ritters kann das Turnier einmal mehr seinen Nutzen erfüllen. Die Champions der Horde und Allianz können ihre Waffenfertigkeiten demonstrieren und für den Tag trainieren, an dem Arthas und seine Diener keine Bedrohung mehr für uns darstellen werden.\n\nIhr habt den Dank des Argentumkreuzzugs, {name}, und all derer, die unserem Ruf gefolgt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13665] = { id = 13665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Sturmwind lieben ihre Ritter über alles und freuen sich darauf, uns gewinnen zu sehen. Damit das auch geschieht, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf das Streitross aus Sturmwind, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Hauptmann Joseph Holley beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr Sturmwind stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13666] = { id = 13666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Einige der Champions glauben, dass eine uralte Waffe aus Nordend ihnen auf dem Turnier Glück bringen wird. Nun habe ich meine Zustimmung gegeben, ihnen bei der Suche nach diesen Waffen zu helfen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Arkanist Taelis beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "An diesen alten Geschichten ist also etwas Wahres dran? Wie es scheint, haben sie in Bezug auf die Qualität der Klinge nicht gelogen. Gut gemacht, {name}. Der Champion, der sie trägt, wird in der Tat ein Glückspilz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13667] = { id = 13667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Argentumturnier", description = "Wir haben Euch hierher eingeladen, damit Ihr Euer Können und Euren Wagemut mit anderen messt, die sich der Geißel tapfer widersetzt haben. Wir hatten viele Meinungsverschiedenheiten, doch nun ist die Zeit gekommen, dass sich Helden aller Lager im Schwertkampf gegenseitig auf die Probe stellen, um sich auf die Begegnung mit unserem gemeinsamen Feind vorzubereiten.\n\nArkanist Taelis ist der Repräsentant des Silberbunds in diesem Turnier. Er wird Euch in die Schriftrollen eintragen und Euer Training beginnen lassen. Ihr findet ihn im großen Zelt der Allianz im nordöstlichen Teil des Geländes.", sourceObjective = "Sprecht mit Arkanist Taelis beim Argentumturnierplatz, um Euch für das Turnier anzumelden.", completion = "Ich habe Euren Namen in die Listen aufgenommen, {name}. Als Streiter werdet Ihr mit anderen zusammen üben, die im Turnier kämpfen möchten, und Eure Fähigkeiten im berittenen Kampf verfeinern. Sobald Ihr Euch bewiesen habt, wird es Euch erlaubt sein, im Auftrag Eurer Hauptstadt dem niedrigsten Rang des Wettkampfes beizutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13668] = { id = 13668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Argentumturnier", description = "Wir haben Euch hierher eingeladen, damit Ihr Euer Können und Euren Wagemut mit anderen messt, die sich der Geißel tapfer widersetzt haben. Wir hatten viele Meinungsverschiedenheiten, doch nun ist die Zeit gekommen, dass sich Helden aller Lager im Schwertkampf gegenseitig auf die Probe stellen, um sich auf die Begegnung mit unserem gemeinsamen Feind vorzubereiten.\n\nMagister Edien Sonnental ist der Repräsentant der Sonnenhäscher in diesem Turnier. Er wird Euch in die Schriftrollen eintragen und Euer Training beginnen lassen. Ihr findet ihn im großen Zelt der Horde im südöstlichen Teil des Geländes.", sourceObjective = "Sprecht mit Magister Edien Sonnental beim Argentumturnierplatz, um Euch für das Turnier anzumelden.", completion = "Ich habe Euren Namen in die Listen aufgenommen, {name}. Als Streiter werdet Ihr mit anderen zusammen üben, die im Turnier kämpfen möchten, und Eure Fähigkeiten im berittenen Kampf verfeinern. Sobald Ihr Euch bewiesen habt, wird es Euch erlaubt sein, im Auftrag Eurer Hauptstadt dem niedrigsten Rang des Wettkampfes beizutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13669] = { id = 13669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Unsere Champions haben Gefallen an uralten Waffen gefunden, die hier in Nordend hergestellt wurden.\n\nDie Barden erzählen Geschichten von Reisenden, die einer einsamen Maid Winterhyazinthen anbieten und dafür Geschenke bekommen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Sammelt die Blumen und bringt sie zum Lampenkreis auf dem Drak'Marsee im Nordosten der Drachenöde in der Nähe von Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt die Klinge von Drak'Mar zu Arkanist Taelis beim Argentumturnierplatz.", progress = "Stimmen die Geschichten der wandernden Barden? Habt Ihr eine Klinge mitgebracht?", completion = "Es besteht kein Zweifel daran, dass dies eine Klinge von außerordentlicher Qualität und Balance ist. Nun verstehe ich, weshalb diese Waffen unter den Champions der Allianz so begehrt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13670] = { id = 13670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Der Knappe des Großchampions von Eisenschmiede hat mir eine interessante Geschichte erzählt.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Arkanist Taelis beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so ausgezeichnet, wie der Knappe meinte, doch woher wusste er von ihr? Das macht nichts - sie wird ihrem neuen Besitzer gute Dienste leisten. Vielleicht ist es nur gerecht, dass der Großchampion von Eisenschmiede der einzige sein wird, der sie trägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13671] = { id = 13671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübung", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Während Ihr auf dem Weg seid, den berittenen Kampf zu beherrschen, vergesst nicht, die Fähigkeiten zu trainieren, die Euch all die Jahre über gut gedient haben. Zeigt uns, dass Ihr der Geißel mit Ehre und Tapferkeit begegnen könnt, und Ihr werdet Euch das Recht verdienen, auf diesem Turnier anzutreten.\n\nReist nach Eiskrone und tötet jeden Diener der Geißel, den Ihr dort seht. Haltet Euch jedoch vom Bombardement fern - man würde Euch überwältigen.", sourceObjective = "Avareth Flinkstoß beim Argentumturnierplatz möchte, dass Ihr 8 Diener der Geißel von Eiskrone tötet. Dazu zählen alle Diener der Geißel im Bereich von Eiskrone, abgesehen vom Bombardement.", progress = "Habt Ihr Euch im Kampf gegen die Geißel erprobt?", completion = "Ihr habt Euch als fähiger Kämpfer erwiesen, {name}, und Ihr werdet dem Rest der Streiter ein Beispiel sein, die da lautstark fordern, im Auftrag der Allianz anzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13672] = { id = 13672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herausforderung gewachsen", description = "Wenn Ihr die Fähigkeiten des Streiters gemeistert habt, könnt Ihr Euch dazu entscheiden, die Herausforderung des Streiters anzunehmen. Sie wird Euer Können im berittenen Kampf auf die Probe stellen und messen, ob Ihr bereit seid, ein Recke zu werden oder nicht. Solltet Ihr bestehen, werdet Ihr der Delegation Eurer Hauptstadt als Recke beitreten können.\n\nKehrt zu mir zurück, wenn Ihr für die Herausforderung bereit seid.", sourceObjective = "Überreicht Arkanist Taelis beim Argentumturnierplatz 15 Siegel des Streiters, um zu zeigen, dass Ihr bereit seid, Euch der Herausforderung des Streiter zu unterziehen.", progress = "Wollt Ihr Euch der Herausforderung des Streiters stellen?", completion = "Sehr gut, ich werde die Vorbereitungen treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13673] = { id = 13673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Einige der Champions glauben, dass eine uralte Waffe aus Nordend ihnen auf dem Turnier Glück bringen wird. Nun habe ich meine Zustimmung gegeben, ihnen bei der Suche nach diesen Waffen zu helfen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Magister Edien Sonnental beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "An diesen alten Geschichten ist also etwas Wahres dran? Wie es scheint, haben sie in Bezug auf die Qualität der Klinge nicht gelogen. Gut gemacht, {name}. Der Champion, der sie trägt, wird in der Tat ein Glückspilz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13674] = { id = 13674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Unsere Champions haben Gefallen an uralten Waffen gefunden, die hier in Nordend hergestellt werden.\n\nDie Barden erzählen Geschichten von Reisenden, die einer einsamen Maid Winterhyazinthen anbieten und dafür Geschenke bekommen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Sammelt die Blumen und bringt sie zum Lampenkreis auf dem Drak'Marsee im Nordosten der Drachenöde in der Nähe von Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt die Klinge von Drak'Mar zu Magister Edien Sonnental beim Argentumturnierplatz.", progress = "Stimmen die Geschichten der wandernden Barden? Habt Ihr eine Klinge mitgebracht?", completion = "Es besteht kein Zweifel daran, dass dies eine Klinge von außerordentlicher Qualität und Balance ist. Nun verstehe ich, weshalb diese Waffen unter den Champions der Allianz so begehrt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13675] = { id = 13675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Einer der Recken von Orgrimmar hat mir eine interessante Geschichte erzählt.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Magister Edien Sonnental beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so ausgezeichnet, wie der Recke meinte, doch woher wusste er von ihr? Das macht nichts - sie wird ihrem neuen Besitzer gute Dienste leisten. Vielleicht ist es nur gerecht, dass der Großchampion von Orgrimmar der einzige sein wird, der sie trägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13676] = { id = 13676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübung", description = "Das Turnier ist eine Gelegenheit, Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Vergesst nicht, auf Eurem Weg zur Beherrschung des berittenen Kampfes auch die Fähigkeiten zu trainieren, die Euch all die Jahre über gut gedient haben. Zeigt uns, dass Ihr der Geißel mit Ehre und Tapferkeit begegnen könnt, und Ihr werdet Euch das Recht verdienen, auf diesem Turnier anzutreten.\n\nReist nach Eiskrone und tötet jeden Diener der Geißel, den Ihr dort seht.", sourceObjective = "Amariel Sonnenschwur beim Argentumturnierplatz möchte, dass Ihr 8 Diener der Geißel von Eiskrone tötet. Dazu zählen alle Diener der Geißel im Bereich von Eiskrone, abgesehen vom Bombardement.", progress = "Habt Ihr Euch im Kampf gegen die Geißel erprobt?", completion = "Ihr habt Euch als fähiger Kämpfer erwiesen, {name}, und Ihr werdet dem Rest der Streiter ein Beispiel sein, die da lautstark fordern, im Auftrag der Horde anzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13677] = { id = 13677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reitgrundlagen", description = "Die meisten Wettkämpfe des Turniers erfordern von den Wettstreitern, dass sie den Kampf auf einem Reittier beherrschen. Um Euch mit dem berittenen Kampf vertraut zu machen, haben wir überall im nördlichen Teil des Turnierplatzes Trainingsattrappen aufgestellt.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und steigt auf den Falkenschreiter der Sonnenhäscher. Macht Euch mit ihm vertraut und besiegt anschließend die drei verschiedenen Arten von Trainingsattrappen.", sourceObjective = "Trefft ein Nahkampfziel 5 Mal mit der Fähigkeit 'Zustoßen' und wendet die Fähigkeit 'Schildbrecher' auf 2 ungeschützte Distanzziele sowie die Fähigkeit 'Sturmangriff' auf 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", completion = "Gut gemacht, {name}. Für diejenigen, die den Kampf zu Boden gewohnt sind, ist es oft sehr schwer, den berittenen Kampf zu erlernen. Ich habe keine Zweifel daran, dass Ihr Euch mit entsprechender Übung weiterhin verbessern werdet - was weitaus mehr ist als das, was ich von manch anderen Kriegern behaupten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13678] = { id = 13678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herausforderung gewachsen", description = "Wenn Ihr die Fähigkeiten des Streiters gemeistert habt, könnt Ihr Euch dazu entscheiden, die Herausforderung des Streiters anzunehmen. Sie wird Euer Können im berittenen Kampf auf die Probe stellen und messen, ob Ihr bereit seid, ein Recke zu werden oder nicht. Solltet Ihr bestehen, werdet Ihr der Delegation Eurer Hauptstadt als Recke beitreten können.\n\nKehrt wieder zu mir zurück, wenn Ihr bereit seid, die Herausforderung anzutreten.", sourceObjective = "Überreicht Magister Edien Sonnental beim Argentumturnierplatz 15 Siegel des Streiters, um zu zeigen, dass Ihr bereit seid, Euch der Herausforderung des Streiters zu unterziehen.", progress = "Wollt Ihr Euch der Herausforderung des Streiters stellen?", completion = "Sehr gut, ich werde die Vorbereitungen treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13679] = { id = 13679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Streiters", description = "Ihr habt hart trainiert, <Streiter/Streiters> {name}, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen geschickten Gegner auf die Probe zu stellen.\n\nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf das Streitross der Quel'dorei, das dort untergebracht ist.\n\nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr Knappe David vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.\n\nViel Glück, {name}. Möget Ihr stets sicher im Sattel sitzen und Eure Pfeile ins Schwarze treffen.", sourceObjective = "Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Arkanist Taelist beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Meine gebührenden Glückwünsche, {name}. Ihr habt Euren Herausforderer geschlagen und Euch das Recht verdient, zum Recken aufzusteigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13680] = { id = 13680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Streiters", description = "Ihr habt hart trainiert, <Streiter/Streiterin> {name}, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen erfahrenen Gegner auf die Probe zu stellen.\n\nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf den Falkenschreiter der Sonnenhäscher.\n\nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr ein Menschenkind, einen Knappen namens David, vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.\n\nViel Glück, {name}. Möget Ihr sicher im Sattel sitzen und Euer Pferd gleichmäßig reiten.", sourceObjective = "Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Magister Edien Sonnental beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.", completion = "Meine gebührenden Glückwünsche, {name}. Ihr habt Euren Herausforderer geschlagen und Euch das Recht verdient, zum Recken aufzusteigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13681] = { id = 13681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Block so der Splitter", description = "Stein für diesen Job zu besorgen war der reinste Alptraum, das kann ich Euch sagen! Es gibt in den Ruinen sichere Orte, an denen es tonnenweise Stein zu finden gibt, doch diese selbstgerechten Paladine wollen einfach nicht zugreifen. Hat was mit unbezahlbaren Artefakten zu tun, oder so was.\n\nWie dem auch sei: Darüber zu jammern wird auch nicht helfen, diesen Ort aufzubauen. In den Fußmarschen und der Bibliothek des Erfinders in den Sturmgipfeln gibt es eine ganze Reihe Titanenruinen. Nehmt meinen, ähm, 'Meißel' mit und seht, ob Ihr diese riesigen Blöcke nicht in brauchbare Stücke zerhauen könnt.", sourceObjective = "Bringt 15 kleine Steinblöcke zu Stümpi Sprengbolz beim Argentumturnierplatz.", progress = "Habt Ihr die Steinblöcke dabei?", completion = "Die sollten reichen. Sagt den Kreuzfahrern bloß nicht, woher Ihr sie habt. Ich bin mir sicher, dass sie sich darüber aufregen würden. Aber hey, es ist ja nicht so, als wären die Titanen für sie zurückgekommen. Wenn's nach mir geht, kann man sie sich einfach nehmen. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13682] = { id = 13682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.\n\nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr und Eure Verbündeten habt das Turnier vor einem vernichtenden Angriff bewahrt. Unsere Himmelsklauenreiter mögen zwar tapfer sein, haben jedoch alle Hände voll damit zu tun, den Frieden auf dem Turnierplatz zu wahren, und sie hätten Mühe damit, den Luftraum gegen die Angriffe des Kults zu verteidigen. Euch gehört der Dank des Argentumkreuzzugs und all derjenigen, die sich hier versammelt haben, um am Wettkampf teilzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13683] = { id = 13683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rituale aufhalten", description = "Ich habe zufällig mit angehört, welchen Verlust Illiyana erfahren musste. Ich kann ihren Wunsch nach Rache verstehen. Ich frage mich, ob Ihr, während Ihr diese ausführt, uns einen Dienst erweisen könntet?\n\nZweifellos habt Ihr bereits die Satyrn von Satyrnaar und Xavian gesehen, wie sie ekelhafte Rituale durchführen. Ich glaube, sie bereiten Rituale vor, die jeden der Nachtelfen, den sie fangen, in Satyrn verwandeln sollen. Wir Draenei möchten ebenfalls nicht, dass diese üble Magie sich verbreitet.\n\nWürdet Ihr die Ritualedelsteine stören während Ihr dort seid?", sourceObjective = "Stört 8 Ritualedelsteine.", completion = "Wir stehen in Eurer Schuld, {class}.\n\nDie Rituale können nicht mehr abgeschlossen werden und die Satyrn kämpfen nun auf verlorenem Posten, da sie ihre Anzahl nicht mehr mehren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13684] = { id = 13684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Sturmwind", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Sturmwind anzutreten, {name}. Nun solltet Ihr mit Marschall Jacob Alerius sprechen, der Sturmwinds Wettkämpfer anführt. Als Großchampion von Sturmwind wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Marschall Jacob Alerius beim Argentumturnierplatz, um ein Recke von Sturmwind zu werden.", completion = "Na dann willkommen an Bord, Recke {name}. Die Delegation von Sturmwind ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13685] = { id = 13685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Eisenschmiede", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Eisenschmiede anzutreten, {name}. Nun solltet Ihr mit Lana Starkhammer sprechen, die die Wettkämpfer von Eisenschmiede anführt. Als Großchampion der Stadt wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Lana Starkhammer beim Argentumturnierplatz, um ein Recke von Eisenschmiede zu werden.", completion = "Gut, Euch kennenzulernen, Recke. Eisenschmiede braucht Wettkämpfer wie Euch, um auf dem Turnier zu bestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13688] = { id = 13688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Gnomeregan", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Gnomeregan anzutreten, {name}. Nun solltet Ihr mit Ambrose Bolzenfunk sprechen, der die Wettkämpfer von Gnomeregan anführt. Als Großchampion der Gnome wird er Euch in ihrem Namen für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Ambrose Bolzenfunk beim Argentumturnierplatz, um ein Recke von Gnomeregan zu werden.", completion = "Na dann willkommen an Bord, Recke {name}. Die Delegation von Gnomeregan ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13689] = { id = 13689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Darnassus", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Darnassus anzutreten, {name}. Nun solltet Ihr mit Jaelyne Abendlied sprechen, die die Wettkämpfer von Darnassus anführt. Als Großchampion der Nachtelfen wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Jaelyne Abendlied beim Argentumturnierplatz, um ein Recke von Darnassus zu werden.", completion = "Willkommen zur Turniersdelegation von Darnassus, {name}. Es wird eine Freude sein, an Eurer Seite zu trainieren und am Wettkampf teilzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13690] = { id = 13690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke der Exodar", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner der Exodar anzutreten, {name}. Nun solltet Ihr Euch Kolosos vorstellen, dem Leiter der Delegation der Exodar. Als Großchampion der Draenei wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Kolosos beim Argentumturnierplatz, um ein Recke der Exodar zu werden.", completion = "Na dann willkommen an Bord, Recke {name}. Die Delegation der Exodar ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13691] = { id = 13691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Orgrimmar", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Orgrimmar anzutreten, {name}. Nun solltet Ihr mit Mokra dem Schädelberster sprechen, der Orgrimmars Wettkämpfer anführt. Als Großchampion von Orgrimmar wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Mokra dem Schädelberster beim Argentumturnierplatz, um ein Recke von Orgrimmar zu werden.", completion = "Ihr wollt also für Orgrimmar antreten? Nur, weil Ihr ein paar Attrappen verhauen habt, heißt das noch lange nicht, dass Ihr auch gewinnen werdet. Doch von nun an werdet Ihr mit den Besten zusammen trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13692] = { id = 13692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert und die See", description = "Mein Schwert ist auf See verloren gegangen. Holt es herauf und bringt es zurück!", sourceObjective = "Der alte Barlo im Kristallsangwald möchte, dass Ihr ihm das Schwert der Ritterwürde bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13693] = { id = 13693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Sen'jin", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Sen'jin anzutreten, {name}. Nun solltet Ihr mit Zul'tore sprechen, der die Krieger von Sen'jin anführt. Als Großchampion der Trolle wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Zul'tore beim Argentumturnierplatz, um ein Recke von Sen'jin zu werden.", completion = "Ihr denkt, dass Ihr das Zeug dafür habt, in Sen'jins Namen am Wettkampf teilzunehmen? Wir werden es herausfinden, denke ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13694] = { id = 13694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Donnerfels", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Donnerfels anzutreten, {name}. Nun solltet Ihr mit Runok Wildmähne sprechen, der Donnerfels' Wettkämpfer anführt. Als Großchampion von Donnerfels wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Runok Wildmähne beim Argentumturnierplatz, um ein Recke von Donnerfels zu werden.", completion = "Im Namen von Donnerfels und seinen Kriegern heiße ich Euch willkommen, {name}. Kämpft unter unserem Banner stets mit Ehre und Tapferkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13695] = { id = 13695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Unterstadt", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Unterstadt anzutreten, {name}. Nun solltet Ihr mit Todespirscher Visceri sprechen, der Unterstadts Wettkämpfer anführt. Als Großchampion wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Todespirscher Visceri beim Argentumturnierplatz, um ein Recke von Unterstadt zu werden.", completion = "Willkommen in der Delegation von Unterstadt, {name}. Als Recke werdet Ihr mit uns trainieren, um Euch auf die höchste Stufe des Wettkampfes vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13696] = { id = 13696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Silbermond", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Silbermond anzutreten, {name}. Nun solltet Ihr mit Eressea Morgensänger sprechen, die Silbermonds Wettkämpfer anführt. Als Großchampion von Silbermond wird sie Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Eressea Morgensänger beim Argentumturnierplatz, um ein Recke von Silbermond zu werden.", completion = "Ihr wollt also für Silbermond antreten? Nun gut. Ich werde Euch in die Namensliste aufnehmen und Ihr könnt sofort damit anfangen, mit den anderen Recken zusammenzuarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13697] = { id = 13697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Mokra dem Schädelberster beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13698] = { id = 13698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprengstoffschreddern", description = "Ich hasse es, Euch wieder dorthin zurückzuschicken, aber Eurer Beschreibung entnehme ich, dass wir es nicht zulassen dürfen, dass sie den ganzen Sprengstoff verwenden, den sie gelagert haben!\n\nEs ist zu gefährlich für Euch, ihn einfach so zu zerstören, aber wenn Ihr einen der Schredder stehlen könntet, bin ich mir sicher, dass er robust genug ist, den Explosionen standzuhalten.\n\nNachdem Ihr den Sprengstoff vernichtet habt, kehrt mit dem Schredder wieder hierher zurück. Es wäre närrisch, ihn wieder der Horde zu überlassen.", sourceObjective = "Verwendet einen Kriegshymnenschredder um 8 Fässer mit Sprengstoff zu vernichten.", completion = "Ich habe die Explosionen bis hierher sehen können! Diesen widerwärtigen Orcs und ihren Goblinlakaien wird es nun schwer fallen, den Wald weiter zu zerstören!\n\nWir können Euch nicht genug danken, {name}. Bitte nehmt dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[13699] = { id = 13699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen Sturmwinds beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Marschall Jacob Alerius beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen Sturmwinds auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13702] = { id = 13702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13703] = { id = 13703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Eisenschmiede", description = "Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Wollt Ihr der Turniersdelegation von Eisenschmiede beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Eisenschmiede ernannt hat, wird Euer Knappe unser Banner in die Schlacht tragen dürfen.", sourceObjective = "Sprecht wieder mit Lana Starkhammer, falls Ihr ein Recke von Eisenschmiede werden wollt.", completion = "Wir sind stolz, dass Ihr Euch dazu entschlossen habt, uns beizutreten, und ich weiß, dass Ihr auf dem Schlachtfeld glänzen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13704] = { id = 13704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Gnomeregan", description = "Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Gnomeregans Delegation könnte von jemandem wie Euch wirklich profitieren.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Gnomeregan ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Ambrose Bolzenfunk, falls Ihr ein Recke von Gnomeregan werden wollt.", completion = "Wir sind stolz, Euch unter uns zählen zu dürfen, {name}, und wir freuen uns darauf, mit Euch zu trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13705] = { id = 13705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke der Exodar", description = "Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation der Exodar beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion der Exodar ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Kolosos, falls Ihr ein Recke der Exodar werden wollt.", completion = "Es ist gut, dass Ihr nun zu uns gehört, {name}. Wir werden alle vom Training mit Euch profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13706] = { id = 13706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Darnassus", description = "Seid willkommen, Champion. Ich habe von Euren Leistungen gehört und wir wären geehrt, wenn Ihr der Delegation von Darnassus beitreten würdet.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Darnassus ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Jaelyne Abendlied, falls Ihr ein Recke von Darnassus werden wollt.", completion = "Die Krieger von Darnassus sind geehrt, an Eurer Seite kämpfen und trainieren zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13707] = { id = 13707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Orgrimmar", description = "Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Orgrimmars Delegation begrüßen zu dürfen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Orgrimmar ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Mokra dem Schädelberster, falls Ihr ein Recke von Orgrimmar werden wollt.", completion = "Dann seid willkommen, {name}. Ich freue mich darauf, Euch beim Training mit meinen Männern zuzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13708] = { id = 13708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Sen'jin", description = "Grüße, Champion. Wenn Ihr wollt, dann würde ich Euch in Sen'jins Turniersdelegation willkommen heißen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Sen'jin ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Zul'tore, falls Ihr ein Recke von Sen'jin werden wollt.", completion = "Ich bin froh, dass Ihr Euch dazu entschlossen habt, uns beizutreten, und freue mich darauf, Euch in Aktion zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13709] = { id = 13709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Donnerfels", description = "Willkommen, Champion. Als Großchampion der Delegation von Donnerfels wäre ich stolz darauf, Euch in unseren Reihen begrüßen zu dürfen, falls Ihr dies wünscht.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Donnerfels ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Runok Wildmähne, falls Ihr ein Recke von Donnerfels werden wollt.", completion = "Es ehrt mich, dass Ihr Euch dazu entschlossen habt, unserer Delegation beizutreten. Ich weiß, dass Ihr uns stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13710] = { id = 13710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Unterstadt", description = "Seid willkommen, Champion. Die Delegation der Verlassenen könnte immer so jemanden wie Euch gebrauchen. Wollt Ihr uns beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Unterstadt ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Todespirscher Visceri, falls Ihr ein Recke von Unterstadt werden wollt.", completion = "Ihr habt eine weise Entscheidung getroffen, {name}. Wir beide werden von dieser Abmachung profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13711] = { id = 13711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Silbermond", description = "Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Silbermonds Delegation begrüßen zu dürfen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Silbermond ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Eressea Morgensänger, falls Ihr ein Recke von Silbermond werden wollt.", completion = "Es wird uns eine Ehre sein, mit Euch zu trainieren und am Wettkampf teilzunehmen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13712] = { id = 13712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung in der Not", description = "Ihr kommt mit mir mit, {name}.\n\nIch kann niemanden sonst erübrigen und wir können es uns nicht leisten, den Splitterholzposten zu verlieren.\n\nBereitet Euch gut vor und sprecht mich wieder an, wenn Ihr soweit seid.", sourceObjective = "Sprecht mit Kadrak am Schutzwall von Mor'shan und begleitet ihn zum Splitterholzposten.", completion = "Gorkas Tod war nicht umsonst, {name}.\n\nDer Splitterholzposten wäre sicher gefallen, wenn wir nicht rechtzeitig gekommen wären.\n\nJetzt müssen wir uns daran machen, die Verteidigung wieder aufzubauen.\n\nEs ist noch nicht vorbei...", sourceObjectiveStatus = "unverified-source-field" }
quests[13713] = { id = 13713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen von Eisenschmiede beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Lana Starkhammer beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen von Eisenschmiede auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13714] = { id = 13714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Lana Starkhammer beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13715] = { id = 13715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Ambrose Bolzenfunk beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
