quests[13722] = { id = 13722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Eressea Morgensänger beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13723] = { id = 13723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen Gnomeregans beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Ambrose Bolzenfunk beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen von Gnomeregan auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13724] = { id = 13724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen der Exodar beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Kolosos beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen der Exodar auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13725] = { id = 13725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen Darnassus beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Jaelyne Abendlied beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen von Darnassus auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13726] = { id = 13726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Mokra dem Schädelberster beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner Orgrimmars die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13727] = { id = 13727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Zul'tore beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner der Dunkelspeere die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13728] = { id = 13728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Runok Wildmähne beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr den Argentumchampion bezwungen?", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner von Donnerfels die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13729] = { id = 13729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Todespirscher Visceri beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr den Argentumchampion bezwungen?", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner von Unterstadt die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13730] = { id = 13730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiel mit dem Teufelsfeuer", description = "<Draaka neigt sich zu Euch, um mit Euch zu sprechen.>\n\nHört... Bevor Ihr etwas sagt, ich WEISS, dass wir uns nicht mit dämonischen Kräften einlassen sollten...\n\nAber seht Euch um! Es herrschen verzweifelte Zeiten, {class}.\n\nWir werden aller Wahrscheinlichkeit nach trotzdem hier sterben. Wir können genauso gut mit Glanz und Glorie untergehen, sage ich!\n\nAlso... Seid Ihr dabei?\n\nNehmt diesen Kanister und begebt Euch nach Südosten zum Dämonenhügel. Verwendet ihn in der Nähe der Felder aus Teufelsfeuer und bringt ihn mir wieder, wenn Ihr ihn gefüllt habt.\n\nOh, und am besten, Ihr sprecht mit niemandem darüber...", sourceObjective = "Draaka im Splitterholzposten möchte, dass Ihr den verstärkten Kanister mit 7 Teufelsfeuern vom Dämonenhügel füllt.", completion = "Oh, ja!\n\nDas wird diesen Elfen eine Lektion erteilen. Seht einfach zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[13731] = { id = 13731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Eressea Morgensänger beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der angebundenen Nähe der Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner von Silbermond die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13732] = { id = 13732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz möchte mit Euch sprechen, {name}, und Euch offiziell beim großen Arenakampf anmelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13733] = { id = 13733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13734] = { id = 13734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
