quests[13755] = { id = 13755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Saandos beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Es ist gut, wenn wir uns daran erinnern, dass die Geißel noch immer da draußen ist, selbst während wir für den Wettkampf trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13756] = { id = 13756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger der Exodar freuen sich darauf zuzusehen, wie wir ihn gewinnen. Damit das auch geschieht, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Azurmythoselekk, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Ranii beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr uns stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13757] = { id = 13757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Jaelyne Abendlied beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13758] = { id = 13758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück! Ich habe meine Klinge verloren!\n\nIch habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt Jaelyne Abendlied beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "<Jaelyne nimmt die Klinge von Drak'Mar entgegen.>\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13759] = { id = 13759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Das ist das letzte Mal, dass ich mich mit einem Todesritter anlege.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon seit so langer Zeit bewacht, {name}.", sourceObjective = "Jaelyne Abendlied beim Argentumturnierplatz möchte, dass Ihr ihr die Winterschneide beschafft.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13760] = { id = 13760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Illestria Klingensänger beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Es ist gut, wenn wir uns daran erinnern, dass die Geißel noch immer da draußen ist, selbst während wir für den Wettkampf trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13761] = { id = 13761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Darnassus freuen sich darauf, zuzusehen, wie wir ihn gewinnen. Damit das auch geschieht, haben sie im Kampf gegen die Recken der anderen Allianzhauptstädte an ihren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nDer Ring der Recken der Allianz befindet sich direkt neben unserem Zelt. Geht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den darnassischen Nebelsäbler, der dort steht, und fordert die Recken heraus.", sourceObjective = "Bringt 3 Male des Recken zu Airae Sternensucher beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr Darnassus stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13762] = { id = 13762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Mokra dem Schädelberster beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13763] = { id = 13763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt Mokra dem Schädelberster beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13764] = { id = 13764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Mokra der Schädelberster beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13765] = { id = 13765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Akinos beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Ich bin mir sicher, dass Ihr uns stolz machen werdet, wenn der Wettkampf anfängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13766] = { id = 13766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlossene Tore", description = "Ich kann es in der Erde spüren, dass weitere Dämonen in unsere Welt gebracht werden. Bald werden es zu viele sein und wir werden von ihnen überrannt werden, ohne Hoffnung darauf, sie zurückzuschlagen.\n\nNehmt diesen Teil von mir und kehrt zum Dämonensturz und zum Dämonenstieg südlich vom Dämonenhügel zurück. Zeigt mit dem Zweig auf ein Dämonentor und konzentriert Euch. Ich habe einen Teil der Lebensenergien des Waldes in seinem Holz gespeichert und er wird das Tor schließen.", sourceObjective = "Schließt mit Knorres Zweig 10 Dämonentore.", completion = "Wenn die Tore geschlossen sind und keine weitere Verstärkung mehr herausströmt, ist es nur eine Frage der Zeit, bevor die Dämonen nicht mehr sind.\n\nIhr seid ein Held des Waldes, {name}. Ich danke Euch im Namen aller Kreaturen im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[13767] = { id = 13767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Wolf aus Orgrimmar, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Morah Worgschwester beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13768] = { id = 13768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Zul'tore beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13769] = { id = 13769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt Zul'tore beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13770] = { id = 13770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Zul'tore beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13771] = { id = 13771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Schattenjäger Mezil-kree beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Ich bin mir sicher, dass Ihr uns stolz machen werdet, wenn der Wettkampf anfängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13772] = { id = 13772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Raptor der Dunkelspeere, der dort steht, und fordert die Recken heraus. Sie warten auf Euch im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Gahju beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Durch das Training mit den anderen Recken werdet Ihr Euch schnell das notwendige Wissen aneignen, mit dem Ihr sie schlagen könnt. Macht weiter so und Ihr werdet keine Probleme damit haben, sie im Wettkampf zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13773] = { id = 13773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Runok Wildmähne beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13774] = { id = 13774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt Runok Wildmähne beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13775] = { id = 13775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Runok Wildmähne beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13776] = { id = 13776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Dern Zorntotem beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Einen ganzen Tag zu trainieren kann nie schaden. Gut zu sehen, dass Ihr in Übung bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13777] = { id = 13777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Mulgorekodo, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Anka Klauenhuf beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13778] = { id = 13778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Todespirscher Visceri beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13779] = { id = 13779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt Todespirscher Visceri beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13780] = { id = 13780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Todespirscher Visceri beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13781] = { id = 13781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Sarah Chalke beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Einen ganzen Tag zu trainieren kann nie schaden. Gut zu sehen, dass Ihr in Übung bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13782] = { id = 13782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Kampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillon, nehmt Eure Lanze, steigt auf das Schlachtross der Verlassenen, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Tierführer Dretch beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", sourceObjectiveStatus = "unverified-source-field" }
