quests[13785] = { id = 13785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Eressea Morgensänger beim Argentumturnierplatz möchte, dass Ihr ihr Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13786] = { id = 13786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Kethiel Sonnenlanze beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Einen ganzen Tag zu trainieren kann nie schaden. Gut zu sehen, dass Ihr in Übung bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13787] = { id = 13787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Falkenschreiter von Silbermond, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Aneera Thuron beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13788] = { id = 13788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.\n\nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.\n\nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar herum.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr habt das Turnier vor einem vernichtenden Angriff bewahrt. Der Argentumkreuzzug und all jene, die hier versammelt sind, stehen in Eurer Schuld und wir werden dafür sorgen, dass sie sich auch daran erinnern. Die Friedensbewahrer und Himmelsklauen machen so einen Wind darum, Schutz zu bieten, doch sie verbringen mehr Zeit damit, Schlägereien zwischen Betrunkenen aufzulösen, als uns vor der Geißel zu beschützen.\n\nMacht nichts - wir beschützen immer die unseren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13789] = { id = 13789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Das Kolosseum befindet sich im gefährlichsten Teil der Welt, {name}. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.", sourceObjective = "Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Anhänger des Kults der Verdammten im Bereich von Eiskrone.", completion = "Ihr seid ein wahrer Champion, {name}, im Ring und auf dem Schlachtfeld. Wir alle müssen wachsam gegenüber der Geißel sein und Ihr seid unseren Brüdern und Eurem eigenen Volke ein Beispiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13790] = { id = 13790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Diejenigen, die Ihr besiegt habt, werden bis zum Beginn des Turniers ihre Anstrengungen verdoppelt haben und danach trachten, ihren Verlust zu rächen, den sie durch Euch erfahren mussten.\n\nEs wäre Euch anzuraten, im Kampf mit den Streitern, die im Ring der Champions auf Euch warten, Eure Fähigkeiten zu verbessern. Nehmt Eure Lanze, geht zur Südseite des Platzes, besteigt eines der Euch zur Verfügung stehenden, angebundenen Reittiere und fordert sie heraus.", sourceObjective = "Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Gut gemacht. Mit den anderen Champions zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Allianz stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13791] = { id = 13791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur'thar und Todessprechers Wacht vertreten.", sourceObjective = "Zor'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", completion = "Ihr habt gute Arbeit dabei geleistet zu zeigen, dass wir unserer Verpflichtung nachkommen und die Geißel bekämpfen, egal wo wir sind oder was wir tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13792] = { id = 13792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenwandler", description = "Jetzt, wo die Dämonentore zerstört sind, muss die Kraft des Waldes wieder regeneriert werden. Das Herz des Waldes muss wiedererlangt werden!\n\nGaivan Schattenwandler, ein mächtiger Druide der Klaue ist Richtung Südwesten am Dämonenhügel vorbei zum Grabhügel von Dor'Danil gegangen. Darin liegt das Herz des Waldes. Es wird von den Druiden von Eschental tief unter der Oberfläche beschützt.\n\nSucht nach Gaivan und erzählt ihm, was sich zugetragen hat, {name}.", sourceObjective = "Sprecht mit Gaivan Schattenwandler, der vor dem Eingang zum Grabhügel von Dor'Danil im Eschental wandelt.", completion = "Ihr seid mutig, hierher zu kommen, {class}, aber Ihr seid vielleicht zu spät. All unsere Druiden sind entweder tot oder sind verrückt geworden.\n\nDennoch, Eure Geschichte ist faszinierend und wenn das, was Ihr sagt, wahr ist, dann muss Knorre das Herz des Waldes bald bekommen oder Eschental wird vergehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13793] = { id = 13793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen besiegt. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt irgendein Euch zur Verfügung stehendes Reittier aus und fordert sie heraus.", sourceObjective = "Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Ihr beherrscht den Umgang mit Eurem Reittier gut, {name}. Mit der Zeit werden Eure Gegner Euch fürchten lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13794] = { id = 13794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eadric der Reine", description = "Ich habe meine Brüder des Argentumkreuzzugs gebeten, eng mit denjenigen zusammenzuarbeiten, die zum Champion aufsteigen. Eadric der Reine, der Großchampion unserer Bruderschaft, hilft dabei, die Trainingsübungen für Champions aller Städte zu beaufsichtigen und sie bei ihren letzten Vorbereitungen für den Turnierwettkampf zu unterstützen.\n\nBitte geht nun und stellt Euch ihm vor. Ich bin mir sicher, dass er begierig darauf sein wird, Eure Bekanntschaft zu machen und Euch auf Eurem Weg zum Wettkampf mit Azeroths größten Champions zu begleiten.", sourceObjective = "Sprecht mit Eadric dem Reinen beim Argentumturnierplatz.", completion = "Gut, Euch endlich kennenzulernen, Champion. Der Hochlord hat mich gebeten, die Koordination der Champions in die Hand zu nehmen, um dafür zu sorgen, dass sie miteinander trainieren und die Verteidigung des Turnierplatzes verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13795] = { id = 13795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geißelbann", description = "Der Delegationsanführer der Ritter der Schwarzen Klinge hat darum gebeten, mit Euch zu sprechen, {class}. Crok Geißelbann ist ein äußerst furchterregender Kämpfer und ich hege keine Zweifel daran, dass er viel von Euch fordern wird.\n\nDie Ritter der Schwarzen Klinge haben auf der Nordseite des Turnierplatzes ihr Lager aufgeschlagen, westlich der Zeltbehausungen der Allianzdelegationen.", sourceObjective = "Sprecht mit Crok Geißelbann beim Argentumturnierplatz.", completion = "Ihr seid also ein Champion geworden, {name}. Ich hatte keine Zweifel daran, dass dies geschehen wird. Wir Ritter wurden in der Hitze des Kampfes ausgebildet, nicht an hölzernen Attrappen. Lasst uns den Paladinen und ihren Gästen zeigen, was die Schlacht aus uns gemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13796] = { id = 13796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Waldes", description = "Ihr müsst das Herz des Waldes um jeden Preis zu Knorre bringen!\n\nEs liegt tief unten im Grabhügel von Dor'Danil - verdorben von der Horde. Nur Knorre kann es reinigen.\n\nUm es vom Fleck zu bewegen, braucht Ihr jedoch eine Kraft der Natur. Wenn Ihr ausreichend reine Erdgeister von den abtrünnigen Druiden und Bewahrern einsammelt, können die Erdgeister zu einer Kraft der Natur vereint werden.\n\nViel Glück, {name}!", sourceObjective = "Beschafft das Herz des Waldes.", progress = "{name}, Ihr seid zurückgekehrt.", completion = "Das Herz des Waldes! Es ist verdorben!\n\n<Das große Urtum knarrt, als seine gigantischen Gliedmaßen damit beginnen, ein Ritual durchzuführen.>\n\nBleibt zurück, {name}, ich werde versuchen, das Herz zu reinigen, bevor alles verloren ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[13797] = { id = 13797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinheiten", description = "Draaka benötigt eine Art von Magnet – etwas, das ihre dämonischen Geschosse anzieht.\n\n<Durak grinst verschlagen.>\n\nZufällig kenne ich eine Methode, die unserem Zwecke dienlich sein sollte.\n\nIhr sucht die Minen nach faustgroßen Erzklumpen ab, und ich bereite eine besondere... Verzauberung vor.", sourceObjective = "Durchsucht die Haufen frischen Gerölls, um 10 Erzklumpen zu finden.", progress = "Habt ihr die Erzklumpen eingesammelt, die wir brauchen?", completion = "Gute Arbeit! Sie sollten den Fluch für unsere Zwecke lange genug tragen können...", sourceObjectiveStatus = "unverified-source-field" }
quests[13798] = { id = 13798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regen der Zerstörung", description = "Gerade rechtzeitig, {class}. Die Elfen haben einen weiteren Angriff gestartet!\n\nVerwendet das verfluchte Erz von den Wachtürmen aus, um die Ziele für Draaka zu markieren.\n\nIhre Projektile werden Eure Ziele treffen und magische Höllenflammen hervorbrechen lassen, die alle Feinde im Umfeld vernichten.\n\nEs gibt starke Vorurteile gegen den Gebrauch von dämonischer Magie. Unberechtigterweise, aber dennoch. Aus diesem Grund werde ich Euch für die Dauer der Mission in einen Wichtel verwandeln, um zu verhindern, dass man Euch erkennt.", sourceObjective = "Nutzt das verfluchte Erz, um Ziele für Draaka zu markieren. Ihr müsst 30 Nachtelfentruppen und 5 tobende Urtume töten.\n\nSprecht mit Durak, um die Wichtelverkleidung aufzufrischen.", completion = "Habt Ihr das gespürt, {name}!?\n\nWie die reine Teufelskraft durch Euer Sein brodelt?\n\nDas ist mit nichts vergleichbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[13799] = { id = 13799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind meine Schlüssel?", description = "Ich kann meine Schlüssel nicht finden! Sicher ist mein böser Zwilling schuld daran. Bitte \"kümmert\" Euch um ihn, {name}.", sourceObjective = "Dr. Finger möchte, dass Ihr seinen bösen Zwilling, Bösfinger, tötet und ihm seine Schlüssel abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13801] = { id = 13801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterelfen", description = "H-habt Ihr das gehört? Geister! Ich hasse Geister!\n\nIhr schauerliches Geheul kommt aus den Grabhügeln im Süden. Ahhh! Macht, dass sie aufhören!\n\nBitte, <mein Herr/gnädiges Fräulein>, ich zahle gutes Geld dafür, wenn Ihr mir diese Stimmen aus dem Kopf schafft!", sourceObjective = "Vernichtet 15 beliebige Nachtelfengeister in den Grabhügeln von Dor’Danil.", completion = "Wohooo!!\n\nIhr habt die Stimmen zum Schweigen gebracht! Habt Dank, vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[13802] = { id = 13802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Goblin mit zwei Gehirnen", description = "Seht Ihr sie dort, entlang der Küste? Was für prächtige Exemplare! Seht Euch nur an, wie Ihre primitive Gesellschaft zusammenarbeitet, wie eine gut geölte Maschine, vom niedrigsten Arbeiter bis zu ihrem Anführer, den ich \"König Burgrurble\" genannt habe.\n\nIch muss einfach ihre Gehirne untersuchen.\"\n\nKönnt Ihr mir ein intaktes Stammhirn eines Sabberzahnmurlocs beschaffen? Tötet sie - für die Wissenschaft!", sourceObjective = "Bringt das Stammhirn eines Sabberzahnmurlocs zu Professor Flozz an der Küste.", sourceObjectiveStatus = "unverified-source-field" }
quests[13803] = { id = 13803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut der Schwachen", description = "Wir wussten, dass die Elfen sich nicht kampflos ergeben würden, aber niemand hatte damit gerechnet, dass sie es fertig bringen, den Splitterholzposten zu belagern...\n\nEs wird Zeit, dass sie dafür bezahlen!\n\nIn der Nähe, im Grabhügel von Dor'Danil, liegt etwas, das dem Feind äußerst teuer ist – das Herz des Waldes.\n\nIch brauche jemanden, der sich bis zum Herzen durchschlägt und es verdirbt.\n\nDieser jemand seid Ihr, {name}.\n\nDoch zunächst bringt meine Axt zu Durak hier in den Minen. Er wird mit dem Blut unserer Feinde etwas anzufangen wissen.", sourceObjective = "Kadrak will, dass Ihr die blutbesudelte Axt zu Durak im Splitterholzposten bringt.\n\nBereitgestellter Gegenstand:", completion = "Das Herz des Waldes verderben?\n\nWie skrupellos – ein äußerst heimtückischer Schlag...\n\nDas gefällt mir!", sourceObjectiveStatus = "unverified-source-field" }
quests[13805] = { id = 13805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten ins Herz!", description = "So...\n\nDas Blut der gefallenen Kaldorei hat sich gewandelt. Es kann jetzt auf das Herz des Waldes im Grabhügel von Dor'Danil angewandt werden. Dadurch wird es gänzlich verdorben werden.\n\nDas heilige Relikt der hochmütigen Elfen wird gegen sie gerichtet. Das ist die Ironie des Lebens!\n\n<Durak lacht gehässig.>\n\nDer Grabhügel schmiegt sich in die Hügel im Südosten. Einer meiner Wichtel hat eine Blutspur gelegt, die vom Eingang bis zum Herzen führt.\n\nEilt Euch! Kadrak ist wahrscheinlich nicht besonders geduldig.\n\nFort mit Euch, {class}.", sourceObjective = "Durak will, dass Ihr das besudelte Blut der Kaldorei auf das Herz des Waldes anwendet.", completion = "Ist es vollbracht?\n\nGute Arbeit, {name}! Das wird ihre Streitkräfte langsam schwächen und auch ihren Geist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13806] = { id = 13806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonendienst", description = "Höret, {class}, ich weiß, dass dieser Angriff auf den Splitterholzposten uns alle mitgenommen hat, aber falls wir die Satyrportale aus den Augen verlieren, steht uns nach dieser Krise eine noch größere bevor.\n\n<Locke starrt Euch ausdruckslos an.>\n\nIhr wisst nichts von den Portalen?\n\nIm Nordosten in der Region von Satyrnaar und Xavian unternehmen die Satyrn den Versuch, Dämonen zu beschwören, um ihre Zahl zu stärken.\n\nWir müssen diese Portale schließen, egal was sich uns dort auch in den Weg stellen mag.", sourceObjective = "Locke Okarr im Splitterholzposten will, dass Ihr 12 Satyrportale in Satyrnaar und Xavian schließt.", completion = "Gute Arbeit, {race}!\n\nEine Sache weniger, um die wir uns sorgen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13808] = { id = 13808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In geheimer Mission", description = "Ich habe eine besondere Aufgabe. Für sie brauche ich einen gut ausgerüsteten, sachkundigen Helfer. Da ich niemanden sonst erübrigen kann, muss ich mich wohl mit Euch begnügen...\n\nDer Feind hat das Holzfällerlager des Kriegshymnenklans angegriffen und vom Rest unserer Streitkräfte abgeschnitten. Eine wichtige Diplomatin der Blutelfen, die auf dem Weg nach Orgrimmar war, wird dort gefangen gehalten.\n\nSie muss befreit werden.\n\nNehmt die Straße nach Nordosten und schüttet dieses Pulver in die schwelende Kohlenpfanne, um unseren Geheimagenten dorthin zu rufen. Tut, was immer er von Euch verlangt.\n\nWegtreten!", sourceObjective = "Kadrak will, dass Ihr das Geheimsignalpulver in die schwelende Kohlenpfanne gegenüber von Satyrnaar schüttet.\n\nBereitgestellter Gegenstand:", completion = "Es gibt für Euch hier alle Hände voll zu tun.\n\nHoffen wir, dass Ihr dieser Aufgabe gewachsen seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[13809] = { id = 13809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.\n\nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", progress = "Habt Ihr den Stoßtrupp des Kults der Verdammten besiegt?", completion = "{name}, Ihr und Eure Verbündeten habt das Turnier vor einem vernichtenden Angriff bewahrt. Unsere Himmelsklauenreiter mögen zwar tapfer sein, haben jedoch alle Hände voll damit zu tun, den Frieden auf dem Turnierplatz zu wahren, und sie hätten Mühe damit, den Luftraum gegen die Angriffe des Kults zu verteidigen. Euch gehört der Dank des Argentumkreuzzugs und all derjenigen, die sich hier versammelt haben, um am Wettkampf teilzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13810] = { id = 13810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Das Kolosseum befindet sich im gefährlichsten Teil der Welt, {name}. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.", sourceObjective = "Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", completion = "Ihr seid ein wahrer Champion, {name}, im Ring und auf dem Schlachtfeld. Wir alle müssen wachsam gegenüber der Geißel sein und Ihr seid unseren Brüdern und Eurem eigenen Volke ein Beispiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13811] = { id = 13811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und von Euren Gegnern lernen. Champions aller Städte üben im Ring der Champions. Nehmt Eure Lanze, steigt auf irgendeins der angebundenen Reittiere, die Euch am Silberbundpavillon zur Verfügung stehen, und fordert sie heraus.", sourceObjective = "Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Gut gemacht. Mit den anderen Champions zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Horde stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13812] = { id = 13812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.\n\nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.\n\nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar herum.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr habt das Turnier vor einem vernichtenden Angriff bewahrt. Der Argentumkreuzzug und all jene, die hier versammelt sind, stehen in Eurer Schuld und wir werden dafür sorgen, dass sie sich auch daran erinnern. Die Friedensbewahrer und Himmelsklauen machen so einen Wind darum, Schutz zu bieten, doch sie verbringen mehr Zeit damit, Schlägereien zwischen Betrunkenen aufzulösen, als uns vor der Geißel zu beschützen.\n\nMacht nichts - wir beschützen immer die unseren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13813] = { id = 13813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur'thar und Todessprechers Wacht vertreten.", sourceObjective = "Zor'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", completion = "Ihr habt gute Arbeit dabei geleistet zu zeigen, dass wir unserer Verpflichtung nachkommen und die Geißel bekämpfen, egal wo wir sind oder was wir tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13814] = { id = 13814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt Euch irgendein zur Verfügung stehendes aus und fordert die Champions zu Übungskämpfen heraus.", sourceObjective = "Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Ihr beherrscht den Umgang mit Eurem Reittier gut, {name}. Mit der Zeit werden Eure Gegner Euch fürchten lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13815] = { id = 13815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stümpfe machen", description = "Wie euch bereits mitgeteilt wurde, sollen wir eine Diplomatin aus dem belagerten Holzfällerlager in Sicherheit bringen.\n\nSo wie es aussieht, ist das einfach unmöglich. Die Elfen halten tausend Pfeile auf die Ausgänge des Holzfällerlagers gerichtet.\n\nZunächst müssen wir ein Ablenkungsmanöver inszenieren – etwas, durch das sie ihren Blick eine Zeitlang vom Holzfällerlager abwenden.\n\nMeine Idee ist einfach. Nehmt diese Axt und fällt die Bäume, die sie in dieser Region pflegen.\n\nWenn Ihr damit fertig seid, verwendet das Signalpulver hier, um wieder mit mir zu sprechen.", sourceObjective = "Krokk will, dass Ihr mit der Splitterholzaxt die Eichen des Eschentals im Holzfällerlager des Kriegshymnenklans fällt.\n\nFalls Ihr das Geheimsignalpulver verliert, sprecht mit Kadrak im Splitterholzposten.", completion = "Gute Arbeit, {name}!\n\nIhr habt die Feinde demoralisiert und Ressourcen für die Horde gesammelt.\n\nHoffen wir, dass der Rest der Mission ebenso gut verläuft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13816] = { id = 13816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Das Himmlische Planetarium", description = "Hört mal, <Kumpel/Mädel>! Das Schicksal von Azeroth steht hier auf dem Spiel.\n\nUnsere einzige Chance ist es, rechtzeitig das Himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.\n\nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.", sourceObjective = "Ausgrabungsleiterin Loren im Archivum möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.", progress = "Habt Ihr ihn gefunden, {name}?", completion = "Verschlossen? Das war ja klar!\n\nIch werde Brann Bescheid sagen... vielleicht kann er etwas im Archivum entdecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13817] = { id = 13817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Datenscheibe des Archivums", description = "Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort \"ARCHIVUM\".\n\nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.", sourceObjective = "Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.", progress = "Die Konsole surrt vor Energie, als sich der runde Aufnahmebehälter öffnet.", completion = "Die Platinscheibe passt perfekt in die Konsole. Sie fängt an, sich zu drehen. Weiße Lichtstrahlen scheinen die darauf befindlichen Informationen abzutasten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13818] = { id = 13818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Algalon", description = "Ihr habt es wirklich geschafft, {name}. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum Himmlischen Planetarium erhaltet.\n\nIhr beeilt Euch besser, <Kumpel/Mädchen>. Die Zeit drängt.", sourceObjective = "Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.", progress = "Die gleißenden Lichter der Konsole scannen mehrmals die Glasoberfläche, gerade so, als ob eine Form von Datenübermittlung erwartet würde.", completion = "Verifizierungsprozess läuft.\n\nZugang zum himmlischen Planetarium gewährt. Bitte Schlüssel entnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13819] = { id = 13819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Ende gut, alles gut", description = "Wir sollten uns jetzt besser beeilen, {name}. Wir müssen den Antwortcode von Dalaran aus übermitteln.\n\nBringt ihn zu Rhonin. Ich treffe Euch dort.", sourceObjective = "Überbringt Rhonin in Dalaran den Antwortcode Alpha.", progress = "Seid Ihr soweit, {name}?", completion = "Ihr seid hier. Lasst uns hoffen, dass das hier klappt. Um unser aller willen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13820] = { id = 13820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Sprengbolz", description = "Der Hochlord hat mich damit beauftragt, das Kolosseum so schnell wie möglich fertig zu stellen. Wir haben unsere Bauarbeiter an das Projekt gesetzt, aber wir mussten sehr schnell feststellen, dass wir Hilfe bei der Beschaffung von Materialien brauchten. Ich habe ein paar Goblins angeheuert, Stumpi Sprengbolz und seinen Bruder Stümpi.\n\nSie beaufsichtigen die Arbeiten am südöstlichen Ende des Turniergeländes. Sprecht mit Stumpi und findet heraus, ob er und sein Bruder noch weitere Hilfe dabei brauchen, das benötigte Baumaterial zu beschaffen.", sourceObjective = "Sprecht mit Stumpi Sprengbolz am Argentumturnierplatz.", completion = "Die Justiziarin hat Euch also geschickt? Gut, gut...\n\nWir können immer Hilfe brauchen bei der, äh, \"Anforderung\" von Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[13821] = { id = 13821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Freyas Siegel", description = "Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.\n\nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.\n\nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.\n\nWas soll ich sagen, {name}, das ist eine ganz schöne Zwickmühle, in der wir da stecken.", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Freyas Siegel, {name}? Habt Ihr es?", completion = "Verdammt gute Arbeit, {name}. Wir sind unserem Ziel, Azeroth zu retten, einen Schritt näher!", sourceObjectiveStatus = "unverified-source-field" }
quests[13822] = { id = 13822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Hodirs Siegel", description = "Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!\n\nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Konntet Ihr das Siegel bekommen, {name}?", completion = "Ihr habt es geschafft! Ich weiß nicht wie, aber Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[13823] = { id = 13823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Thorims Siegel", description = "Thorim ist nicht er selbst, {name}. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.\n\nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.\n\nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!\n\nIhr müsst ihn zur Vernunft bringen und zwar schnell.\n\nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Nun, {name}? Habt Ihr's?", completion = "Ihr werdet wohl nie aufhören, mich zu beeindrucken, {name}.\n\nIhr und ich sollten mal ein Bierchen trinken gehen, nachdem wir mit all dem hier durch sind. Mein Wort drauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[13824] = { id = 13824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Mimirons Siegel", description = "Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.\n\nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, um sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Konntet Ihr das Siegel an Euch bringen, {name}?", completion = "Das muss man Euch wirklich lassen, {name}. Unsere Chancen stehen vielleicht nicht zum Besten, aber wenn Ihr mit anpackt fühle ich mich gleich viel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13825] = { id = 13825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muschelette Surprise", sourceObjective = "Hey, ich erinnere mich an Euch! Seid Ihr nicht {name}? Ihr habt mir doch mal geholfen, das ganze Muschelette zu machen!\n\nIch sag Euch was: Kommt näher und ich zeige Euch mein neustes Rezept - es ist einfach und köstlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[13826] = { id = 13826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat Pagle, Extremangler", sourceObjective = "Na, aber hallo, {name}. Entweder lässt mein Gedächtnis mich langsam im Stich oder ich habe vergessen, Euch das hier zu geben, als wir uns das letzte Mal gesprochen haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[13828] = { id = 13828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Nahkampf beherrschen", description = "Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.", sourceObjective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet 5 Mal die Fähigkeit 'Zustoßen' gegen ein Nahkampfziel an. Kehrt anschließend zu Arkanist Taelis beim Argentumturnierplatz zurück.", completion = "Behaltet die Worte des Meisters im Kopf, während Ihr mit den Übungsattrappen trainiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13829] = { id = 13829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Nahkampf beherrschen", description = "Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf den Falkenschreiter der Sonnenhäscher, der gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.", sourceObjective = "Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet 5 Mal die Fähigkeit 'Zustoßen' auf ein Nahkampfziel an. Kehrt anschließend zu Magister Edien Sonnental beim Argentumturnierplatz zurück.", completion = "Behaltet die Worte des Meisters im Kopf, während Ihr mit den Übungsattrappen trainiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13830] = { id = 13830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geisterfisch", description = "Jeder Angler in Nordend, der sein Geld wert ist, weiß über den Pygmäenschiffshalter Bescheid. Er ist nicht essbar, manchmal jedoch für Alchemisten nützlich.\n\nEs gibt jedoch einen Fisch, einen etwas verstohleneren, der sich zwischen den Schiffshaltern im Flussnabel im Sholazarbecken versteckt: der Phantomgeisterfisch. Außerhalb des Wassers werden sie zunehmend lichtdurchlässig, bis sie schließlich ganz verschwinden. Einige nehmen an, dass sie nach Sholazar zurückkehren, andere wiederum sind etwas... abergläubischer.\n\nIch möchte, dass Ihr diesen Fisch fangt und um jeden Preis hinter sein Geheimnis kommt!", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr hinter das Geheimnis des Phantomgeisterfischs kommt.", completion = "Man wird also unsichtbar, wenn man ihn isst... was für eine seltsame Verteidigung dieser Fisch doch entwickelt hat.\n\nIch brauch ein Weilchen, um das zu verdauen - Wortspiel nicht beabsichtigt, {name}; wirklich. Wieso kommt Ihr nicht morgen wieder?", sourceObjectiveStatus = "unverified-source-field" }
quests[13831] = { id = 13831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besorgniserregende Rezepte", description = "Hier steht eine einfache, hastig zusammengezimmerte Werkbank eines Apothekers, die unter der Last gekritzelter Notizen und giftigem Gebräu fast zusammenbricht. Es sieht so aus, als hätten die Verlassenen auch Faulhufs Handwerk untersucht. Ihr schnappt Euch die Notiz, die am wichtigsten aussieht und bereitet Euch darauf vor, alles zu zerstören, bevor Ihr dem Baumwahrer von Eurer Entdeckung berichtet.", sourceObjective = "Bringt die Notizen des Apothekers zu Tharnariun Baumwahrer in Lor'danel.", progress = "Was ist das? Habt Ihr noch etwas in der Höhle gefunden?", completion = "<Tharnariun Baumwahrer durchblättert die Notizen, während Ihr Euren Bericht abliefert, sein Gesicht verfinstert sich sorgenvoll.>\n\nDie Verlassenen interessieren sich für die Arbeit von Faulhuf? Mir dreht sich der Magen um, wenn ich daran denke, was sie mit seiner Verderbnis alles anrichten könnten. Ihr habt gut daran getan, die Arbeit zu zerstören, aber die Notizen beunruhigen mich sehr. Was haben die Verlassenen hier zu suchen? Arbeiten sie mit den Splitterspeertrollen im Norden zusammen? Sorgen über Sorgen, {class}. Ich bin froh, dass Ihr hier seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[13832] = { id = 13832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perle der Kanalisation", description = "Schwer zu glauben, dass die meisten Leute, wenn sie zum Angeln in die Kanalisation von Dalaran gehen, nach Riesenratten und mutierten Fischen suchen. Besonders dann, wenn im Wasser Unmengen unbezahlbarer Juwelen zu finden sind - von gebrochenen Herzen, Dieben und achtlosen Trunkenbolden weggeworfen.\n\nDer Trick bei der Sache ist, Euren Haken am Boden entlang zu ziehen, und wenn Ihr etwas gefunden habt, beim Hochziehen nicht zu viel Kraft zu verwenden. Versucht es einmal, {name}. Ich wäre dazu bereit, was auch immer Ihr findet gegen ein paar meiner eigenen Schmuckstücke einzutauschen.", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr korrodierten Schmuck bringt.", progress = "Hattet Ihr Glück?", completion = "Also, das sieht aus, als könnte es wertvoll sein. Schwer zu sagen, bis es gesäubert und geschätzt wurde, aber ich bin noch immer dazu bereit, den Handel einzugehen, wenn Ihr es auch seid.", sourceObjectiveStatus = "unverified-source-field" }
